INSERT INTO public.topics (id, title, slug, usmle_step, "order", section, is_free_demo, mcq_count, case_count)
INSERT INTO public.mcqs (topic_id, question, options, correct_index, explanation, difficulty, "order", type) VALUES
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 45-year-old woman reports 6 months of heartburn occurring 3 to 4 times per week, worse after meals and when lying flat, with sour regurgitation into her mouth. She denies dysphagia, odynophagia, weight loss, vomiting, or melena. Physical examination is unremarkable. What is the most appropriate next step in management?', '["Upper endoscopy now", "Empiric once-daily proton pump inhibitor for 8 weeks", "24-hour ambulatory pH monitoring", "Barium swallow study", "Bedtime H2-receptor antagonist alone"]'::jsonb, 1, 'Classic gastroesophageal reflux disease without alarm features is managed with an empiric once-daily proton pump inhibitor for 8 weeks, which is the most effective therapy for symptom relief and mucosal healing. Upper endoscopy is reserved for alarm features, refractory symptoms, or Barrett''s screening, and is not the first step here. Ambulatory pH monitoring is used for refractory reflux or before antireflux surgery, not for initial diagnosis. A barium swallow has poor sensitivity for reflux. H2-receptor antagonists are less effective than proton pump inhibitors for healing esophagitis and controlling symptoms.', 'Easy', 1, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 58-year-old man has persistent heartburn despite 8 weeks of once-daily omeprazole 20 mg. He denies dysphagia, weight loss, vomiting, or gastrointestinal bleeding. He takes no NSAIDs and does not smoke. What is the most appropriate next step?', '["Double the proton pump inhibitor dose", "Switch to an H2-receptor antagonist", "Upper endoscopy", "24-hour ambulatory pH monitoring", "Add a prokinetic agent"]'::jsonb, 2, 'Refractory gastroesophageal reflux disease after 8 weeks of once-daily proton pump inhibitor therapy warrants upper endoscopy to evaluate for erosive esophagitis, Barrett''s esophagus, eosinophilic esophagitis, or a peptic stricture that would explain persistent symptoms. Doubling the proton pump inhibitor dose is sometimes tried in practice, but endoscopy is the recommended next diagnostic step when symptoms persist despite adequate acid suppression. Switching to an H2-receptor antagonist is a step down in acid suppression and is unlikely to help. Ambulatory pH monitoring is performed after endoscopy if it is normal, to confirm ongoing reflux. Prokinetic agents are not routinely recommended for refractory reflux.', 'Medium', 2, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 62-year-old man with 15 years of gastroesophageal reflux disease reports progressive difficulty swallowing solids, then liquids, over 3 months, with 8 kg of unintentional weight loss. He has little heartburn now. Physical examination shows a thin man with no palpable lymphadenopathy. What is the most appropriate next step?', '["Upper endoscopy", "Empiric proton pump inhibitor trial", "Barium swallow study", "24-hour ambulatory pH monitoring", "CT scan of the chest"]'::jsonb, 0, 'Progressive dysphagia and weight loss are alarm features that require urgent upper endoscopy to exclude an esophageal stricture or malignancy, and to allow biopsy. An empiric proton pump inhibitor trial would delay diagnosis of a potentially malignant obstruction. A barium swallow can suggest a stricture but cannot provide tissue diagnosis. Ambulatory pH monitoring evaluates acid exposure and does not assess obstruction. CT of the chest is used for staging after a tissue diagnosis is established, not as the initial test.', 'Medium', 3, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 60-year-old white man with a body mass index of 34 kg/m2 has had gastroesophageal reflux disease for 12 years and smokes one pack of cigarettes daily. He reports chronic heartburn controlled with a proton pump inhibitor and has no dysphagia or weight loss. Which of the following is the most appropriate screening recommendation for Barrett''s esophagus?', '["No screening is needed", "Continue proton pump inhibitor alone", "24-hour ambulatory pH monitoring", "Screening upper endoscopy", "CT scan of the abdomen"]'::jsonb, 3, 'Barrett''s esophagus screening is recommended in patients with chronic gastroesophageal reflux disease and at least three risk factors: male sex, white race, age over 50 years, central obesity, and smoking. This patient has all five risk factors, so screening is clearly indicated. Screening upper endoscopy with biopsies is the appropriate test because it directly visualizes and samples the esophageal mucosa. Continuing a proton pump inhibitor alone controls symptoms but does not detect Barrett''s mucosa. Ambulatory pH monitoring measures acid exposure, not mucosal metaplasia. CT of the abdomen cannot detect Barrett''s esophagus.', 'Medium', 4, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 55-year-old man is found to have a 3-cm segment of Barrett''s esophagus on upper endoscopy. Biopsies show intestinal metaplasia without dysplasia. He is started on a proton pump inhibitor. What is the recommended surveillance interval?', '["Upper endoscopy every year", "Upper endoscopy every 6 months", "No further surveillance", "Esophagectomy", "Upper endoscopy every 3 to 5 years"]'::jsonb, 4, 'Nondysplastic Barrett''s esophagus is managed with surveillance upper endoscopy every 3 to 5 years to detect progression to dysplasia or adenocarcinoma while it is still treatable. Annual endoscopy is more frequent than recommended for nondysplastic disease and is reserved for low-grade dysplasia. Six-month intervals are used after endoscopic eradication therapy, not for routine surveillance of nondysplastic Barrett''s. No surveillance at all would miss progression to cancer. Esophagectomy is a major operation that is not indicated in the absence of dysplasia or malignancy. Patients should remain on a proton pump inhibitor between surveillance examinations.', 'Medium', 5, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 63-year-old man with a 5-cm segment of Barrett''s esophagus undergoes surveillance endoscopy. Biopsies show high-grade dysplasia, confirmed on a second endoscopy by an expert gastrointestinal pathologist. He is otherwise healthy. What is the most appropriate next step in management?', '["Endoscopic eradication therapy with radiofrequency ablation", "Esophagectomy", "High-dose proton pump inhibitor alone", "Annual surveillance endoscopy", "Repeat biopsy in 1 year"]'::jsonb, 0, 'High-grade dysplasia in Barrett''s esophagus is treated with endoscopic eradication therapy, typically radiofrequency ablation with or without endoscopic mucosal resection of visible lesions, which is effective and has much lower morbidity than surgery. Esophagectomy is reserved for endoscopic therapy failure, nodular disease not amenable to resection, or invasive cancer. A proton pump inhibitor alone controls acid but does not treat dysplasia. Surveillance alone risks progression to adenocarcinoma. Repeating biopsy in one year only delays definitive therapy. Expert pathology review is essential before committing to eradication therapy.', 'Hard', 6, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 38-year-old man with HIV infection and a CD4 count of 45 cells/mm3 reports severe pain on swallowing for 2 weeks. Upper endoscopy shows several large, shallow, linear ulcers in the mid-esophagus. Biopsy shows cells with intranuclear inclusions. What is the most appropriate treatment?', '["Fluconazole", "Acyclovir", "Proton pump inhibitor", "Trimethoprim-sulfamethoxazole", "Ganciclovir"]'::jsonb, 4, 'Cytomegalovirus esophagitis occurs in advanced HIV infection and presents with odynophagia and large, shallow, linear ulcers; intranuclear inclusions on biopsy confirm the diagnosis, and ganciclovir is the treatment of choice. Fluconazole treats Candida esophagitis, which causes white plaques rather than large ulcers. Acyclovir treats herpes simplex virus esophagitis, which causes small, deep, punched-out ulcers or vesicles. A proton pump inhibitor treats reflux disease, not viral infection. Trimethoprim-sulfamethoxazole treats Pneumocystis pneumonia, not esophagitis. Valganciclovir is an oral alternative to intravenous ganciclovir, and antiretroviral therapy should be optimized to restore immunity.', 'Medium', 7, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 42-year-old woman with HIV infection and a CD4 count of 120 cells/mm3 reports difficulty swallowing for 1 week. Upper endoscopy shows white plaques throughout the esophagus that do not scrape off with the endoscope. What is the most appropriate treatment?', '["Nystatin swish and swallow", "Acyclovir", "Fluconazole", "Ganciclovir", "Proton pump inhibitor"]'::jsonb, 2, 'Esophageal candidiasis in an immunocompromised patient presents with dysphagia and white plaques, and systemic fluconazole is the first-line treatment for esophageal disease because it achieves adequate tissue levels. Nystatin is a topical agent effective only for oral thrush and does not treat esophageal infection. Acyclovir treats herpes simplex virus esophagitis, which causes small ulcers rather than plaques. Ganciclovir treats cytomegalovirus esophagitis. A proton pump inhibitor treats reflux disease, not fungal infection. If fluconazole fails, an echinocandin such as caspofungin is used, and the underlying immunodeficiency should also be addressed.', 'Easy', 8, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 28-year-old man with a history of asthma and eczema reports intermittent difficulty swallowing solid foods and two episodes of food impaction over the past year. Upper endoscopy shows esophageal rings, linear furrows, and white exudates. Esophageal biopsies show 25 eosinophils per high-power field. What is the most likely diagnosis?', '["Gastroesophageal reflux disease", "Achalasia", "Schatzki ring", "Eosinophilic esophagitis", "Candida esophagitis"]'::jsonb, 3, 'Eosinophilic esophagitis presents in young atopic patients with solid-food dysphagia and food impactions; endoscopy shows rings, furrows, and exudates, and biopsy with 15 or more eosinophils per high-power field confirms the diagnosis. Gastroesophageal reflux disease causes heartburn and does not produce esophageal rings. Achalasia causes dysphagia to solids and liquids with absent peristalsis. A Schatzki ring is a thin mucosal ring at the gastroesophageal junction without eosinophilia. Candida esophagitis causes white plaques in immunocompromised patients. Proton pump inhibitors are tried first because some patients have proton pump inhibitor-responsive esophageal eosinophilia, and dietary elimination is another effective strategy.', 'Medium', 9, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 30-year-old woman with eosinophilic esophagitis has persistent dysphagia despite an 8-week proton pump inhibitor trial. She has no esophageal stricture on endoscopy. What is the most appropriate next step in management?', '["Systemic prednisone", "Swallowed fluticasone", "Esophageal dilation", "Fundoplication", "H2-receptor antagonist"]'::jsonb, 1, 'Swallowed topical corticosteroids such as fluticasone or budesonide slurry are first-line therapy for eosinophilic esophagitis after proton pump inhibitor failure, reducing eosinophilic inflammation with minimal systemic absorption. Systemic prednisone has more adverse effects and is reserved for severe or refractory cases. Esophageal dilation treats fibrotic strictures but does not reduce inflammation. Fundoplication treats reflux disease, not eosinophilic esophagitis. H2-receptor antagonists are ineffective for this condition. Patients should also be evaluated for food allergies and may benefit from a six-food elimination diet, with repeat endoscopy and biopsy to confirm histologic remission.', 'Medium', 10, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 32-year-old woman taking doxycycline for acne reports 5 days of retrosternal pain and painful swallowing. Upper endoscopy shows a single mid-esophageal ulcer. She is afebrile and has no oral lesions. What is the most appropriate management?', '["Stop doxycycline and provide supportive care", "Continue doxycycline and start a proton pump inhibitor", "Fluconazole", "Acyclovir", "Esophageal dilation"]'::jsonb, 0, 'Pill-induced esophagitis from doxycycline, and also from NSAIDs, bisphosphonates, and potassium chloride, causes mid-esophageal ulceration with retrosternal pain and odynophagia. Management is discontinuing the offending drug, taking pills with a full glass of water, and remaining upright afterward. Continuing the drug worsens the injury. Fluconazole treats Candida esophagitis, which causes white plaques. Acyclovir treats herpes simplex virus esophagitis. Esophageal dilation is for strictures, not acute pill-induced injury. A short course of a proton pump inhibitor or sucralfate can soothe the injured mucosa, and most patients recover fully within days to weeks after the drug is stopped.', 'Easy', 11, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 45-year-old woman reports progressive difficulty swallowing solids and liquids, regurgitation of undigested food, and 6 kg of weight loss over 6 months. A barium swallow shows a dilated esophagus with tapering at the gastroesophageal junction. Manometry shows absent peristalsis and failure of lower esophageal sphincter relaxation. What is the most likely diagnosis?', '["Diffuse esophageal spasm", "Scleroderma", "Achalasia", "Esophageal cancer", "Gastroesophageal reflux disease"]'::jsonb, 2, 'Achalasia is characterized by absent esophageal peristalsis with failure of lower esophageal sphincter relaxation, producing dysphagia to both solids and liquids, regurgitation, and weight loss, with a bird''s beak tapering on barium swallow. Diffuse esophageal spasm shows premature contractions with normal sphincter relaxation. Scleroderma causes absent peristalsis but a hypotensive sphincter with severe reflux. Esophageal cancer causes mechanical obstruction from a mass. Gastroesophageal reflux disease causes heartburn, not aperistalsis. Manometry is the gold standard for diagnosis, and endoscopy is performed first to exclude a malignancy mimicking achalasia, known as pseudoachalasia.', 'Medium', 12, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 50-year-old man is diagnosed with achalasia after manometry shows absent peristalsis and incomplete lower esophageal sphincter relaxation. He is otherwise healthy and a good surgical candidate. What is the most appropriate definitive treatment?', '["Nifedipine", "Botulinum toxin injection", "Pneumatic dilation", "Heller myotomy", "Proton pump inhibitor"]'::jsonb, 3, 'Heller myotomy, or peroral endoscopic myotomy, is the definitive and most durable therapy for achalasia in a good surgical candidate, relieving dysphagia by dividing the lower esophageal sphincter. Nifedipine and botulinum toxin injection are temporizing measures with short-lived benefit and are reserved for patients who cannot undergo definitive therapy. Pneumatic dilation is effective but less durable and carries a risk of perforation. A proton pump inhibitor treats reflux disease, not achalasia. A partial fundoplication is usually added to the myotomy to reduce postoperative reflux, which is the main long-term complication.', 'Medium', 13, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 55-year-old woman reports intermittent episodes of chest pain and difficulty swallowing over the past year. Cardiac evaluation is normal. High-resolution manometry shows premature contractions with a distal latency of 3.5 seconds and normal lower esophageal sphincter relaxation. What is the most likely diagnosis?', '["Achalasia", "Diffuse esophageal spasm", "Nutcracker esophagus", "Gastroesophageal reflux disease", "Angina pectoris"]'::jsonb, 1, 'Diffuse esophageal spasm is defined by premature contractions with a distal latency under 4.5 seconds and preserved lower esophageal sphincter relaxation, causing intermittent chest pain and dysphagia. Achalasia is distinguished by failure of sphincter relaxation. Nutcracker esophagus, or hypercontractile esophagus, has normal latency with very high-amplitude contractions. Gastroesophageal reflux disease causes heartburn without manometric spasm. Angina is exertional cardiac pain without dysphagia and with normal esophageal motility. Treatment is usually a calcium channel blocker or a tricyclic antidepressant for pain, and nitrates can also relieve spasm.', 'Hard', 14, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 68-year-old man with a 40 pack-year smoking history and heavy alcohol use reports progressive difficulty swallowing solids, then liquids, over 4 months, with 10 kg of unintentional weight loss. Physical examination is unremarkable. What is the most appropriate initial diagnostic test?', '["Barium swallow study", "CT scan of the chest", "24-hour ambulatory pH monitoring", "Esophageal manometry", "Upper endoscopy with biopsy"]'::jsonb, 4, 'Suspected esophageal cancer, particularly squamous cell carcinoma associated with smoking and alcohol use in the mid-esophagus, requires upper endoscopy with biopsy for tissue diagnosis. A barium swallow can show a mass but cannot provide histology. CT of the chest is used for staging after the diagnosis is established. Ambulatory pH monitoring evaluates reflux disease. Manometry evaluates motility disorders and does not diagnose cancer. Adenocarcinoma, by contrast, arises in the distal esophagus from Barrett''s esophagus and is linked to chronic reflux and obesity rather than smoking and alcohol.', 'Medium', 15, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 48-year-old man reports 2 months of epigastric pain that worsens with eating, with 3 kg of weight loss. He takes naproxen daily for osteoarthritis. He denies vomiting, melena, or hematemesis. What is the most likely diagnosis?', '["Gastric ulcer", "Duodenal ulcer", "Gastroesophageal reflux disease", "Gastritis", "Gastric cancer"]'::jsonb, 0, 'Gastric ulcer pain typically worsens with eating and is associated with NSAID use and weight loss. Duodenal ulcer pain is relieved by food and is worse at night or when fasting. Gastroesophageal reflux disease causes retrosternal burning rather than epigastric pain. Gastritis causes diffuse epigastric discomfort without a discrete ulcer. Gastric cancer is possible and must be excluded by biopsy, but a benign gastric ulcer is the most likely diagnosis in this presentation. All gastric ulcers require endoscopy with biopsy because a malignant ulcer can look identical to a benign one.', 'Easy', 16, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 35-year-old man reports 3 months of dyspepsia with epigastric burning and bloating. He has no dysphagia, weight loss, vomiting, or gastrointestinal bleeding. He wishes to be tested noninvasively for Helicobacter pylori. Which test best detects active infection?', '["Serum Helicobacter pylori IgG", "Upper endoscopy", "Urea breath test", "Barium study", "Complete blood count"]'::jsonb, 2, 'The urea breath test, or stool antigen test, detects active Helicobacter pylori infection and is the preferred noninvasive test. Serum IgG cannot distinguish active from past infection. Upper endoscopy is invasive and is reserved for patients with alarm features. A barium study does not detect Helicobacter pylori. A complete blood count does not diagnose this infection. The urea breath test works because Helicobacter pylori produces urease, which splits labeled urea into carbon dioxide that is measured in exhaled breath, and it is also used to confirm eradication.', 'Medium', 17, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 42-year-old man is found to have Helicobacter pylori infection. He has a documented penicillin allergy and lives in an area with high clarithromycin resistance. Which treatment regimen is most appropriate?', '["Triple therapy with proton pump inhibitor, clarithromycin, and amoxicillin", "Proton pump inhibitor, clarithromycin, and metronidazole", "Proton pump inhibitor alone", "Bismuth quadruple therapy", "Sequential therapy"]'::jsonb, 3, 'Bismuth quadruple therapy with a proton pump inhibitor, bismuth, tetracycline, and metronidazole is preferred when there is penicillin allergy and high clarithromycin resistance. Standard triple therapy fails with clarithromycin resistance, and amoxicillin is contraindicated by penicillin allergy. A regimen of proton pump inhibitor, clarithromycin, and metronidazole also relies on clarithromycin. A proton pump inhibitor alone does not eradicate Helicobacter pylori. Sequential therapy depends on clarithromycin and is not appropriate here. Bismuth quadruple therapy is given for 14 days, and a test of cure is required afterward to confirm that eradication succeeded.', 'Hard', 18, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 50-year-old woman completed 14 days of bismuth quadruple therapy for Helicobacter pylori infection 4 weeks ago. She feels well. What is the most appropriate test of cure?', '["Serum Helicobacter pylori IgG", "Repeat upper endoscopy", "Stool antigen test at 1 week", "No test of cure is needed", "Urea breath test now, with proton pump inhibitor held for 2 weeks"]'::jsonb, 4, 'Test of cure uses a urea breath test or stool antigen test at least 4 weeks after completing therapy, with the proton pump inhibitor held for at least 2 weeks to avoid false-negative results. Serology remains positive after eradication and cannot confirm cure. Repeat endoscopy is unnecessary without alarm features. Testing at 1 week is too early and may be falsely negative. A test of cure is recommended for all patients treated for Helicobacter pylori. Antibiotics and bismuth should also be stopped for at least 4 weeks before testing, since they can suppress the organism and cause false negatives.', 'Medium', 19, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 60-year-old man presents with melena for 2 days. His blood pressure is 92/60 mmHg, heart rate 118/min, and hemoglobin 7.8 g/dL. He has received intravenous fluids and a proton pump inhibitor infusion. What is the most appropriate next step?', '["CT angiography", "Colonoscopy", "Intravenous octreotide", "Emergent surgery", "Upper endoscopy within 24 hours"]'::jsonb, 4, 'Acute upper gastrointestinal bleeding requires upper endoscopy within 24 hours after resuscitation and intravenous proton pump inhibitor therapy, for both diagnosis and endoscopic hemostasis. CT angiography is reserved for cases where endoscopy fails or bleeding is obscure. Colonoscopy evaluates lower gastrointestinal bleeding. Intravenous octreotide is used for variceal bleeding, not peptic ulcer bleeding. Surgery is a last resort after failed endoscopic and angiographic therapy. Before endoscopy, resuscitation includes large-bore intravenous access, transfusion for a hemoglobin below 7 g/dL, and correction of coagulopathy.', 'Medium', 20, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 55-year-old man presents with sudden severe epigastric pain that began 4 hours ago. His abdomen is rigid with rebound tenderness. An upright chest radiograph shows free air under the diaphragm. What is the most appropriate management?', '["Emergent surgical repair", "Intravenous proton pump inhibitor and observation", "Upper endoscopy", "CT scan of the abdomen", "Nasogastric tube alone"]'::jsonb, 0, 'A perforated peptic ulcer with free intraperitoneal air and peritonitis requires emergent surgical repair, such as a Graham patch, to close the perforation and wash out contamination. Intravenous proton pump inhibitor therapy and observation are inadequate for peritonitis. Upper endoscopy is contraindicated because insufflation worsens the leak. CT of the abdomen delays definitive care when the diagnosis is already clear. A nasogastric tube alone does not treat peritonitis. Broad-spectrum antibiotics and intravenous fluids are started immediately, and Helicobacter pylori testing and proton pump inhibitor therapy follow after the operation.', 'Medium', 21, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 70-year-old woman taking naproxen daily for osteoarthritis reports epigastric pain for 3 weeks. Upper endoscopy shows a 1.5-cm gastric ulcer. Biopsies are negative for malignancy and Helicobacter pylori. What is the most appropriate management?', '["Continue naproxen and add misoprostol", "Acetaminophen alone", "Stop naproxen and start a proton pump inhibitor", "H2-receptor antagonist alone", "Surgery"]'::jsonb, 2, 'An NSAID-induced gastric ulcer requires discontinuing the NSAID and starting a proton pump inhibitor to allow healing. Continuing the NSAID perpetuates mucosal injury. Misoprostol is used for prophylaxis, not for treating an established ulcer. Acetaminophen alone does not heal the ulcer. H2-receptor antagonists are less effective than proton pump inhibitors for ulcer healing. Surgery is reserved for complications such as bleeding or perforation. If the NSAID cannot be stopped, a cyclooxygenase-2 selective agent plus a proton pump inhibitor is the safest option, and Helicobacter pylori should be tested and treated.', 'Medium', 22, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 68-year-old man in the intensive care unit has been mechanically ventilated for 4 days and has coagulopathy with an INR of 2.1. His nasogastric aspirate shows coffee-ground material. Which prophylactic agent should he have received to prevent this complication?', '["H2-receptor antagonist", "Sucralfate", "No prophylaxis", "Proton pump inhibitor", "Misoprostol"]'::jsonb, 3, 'Stress ulcer prophylaxis is indicated in critically ill patients with risk factors such as mechanical ventilation for more than 48 hours or coagulopathy, and a proton pump inhibitor is preferred over H2-receptor antagonists for preventing clinically important bleeding. H2-receptor antagonists are less effective than proton pump inhibitors. Sucralfate is less effective for bleeding prophylaxis. Withholding prophylaxis leaves a high-risk patient unprotected. Misoprostol is not used for stress ulcer prophylaxis. Prophylaxis should be stopped once the patient is eating or no longer critically ill, since prolonged acid suppression increases the risk of pneumonia and Clostridioides difficile infection.', 'Hard', 23, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 30-year-old woman reports epigastric pain and fullness for 6 months. Upper endoscopy is normal, Helicobacter pylori testing is negative, and she has no dysphagia, weight loss, vomiting, or gastrointestinal bleeding. What is the most likely diagnosis?', '["Gastroesophageal reflux disease", "Functional dyspepsia", "Peptic ulcer disease", "Gastroparesis", "Biliary colic"]'::jsonb, 1, 'Functional dyspepsia is chronic epigastric pain or fullness with a normal endoscopy and no Helicobacter pylori infection or alarm features. Gastroesophageal reflux disease causes retrosternal burning rather than epigastric pain. Peptic ulcer disease would show an ulcer on endoscopy. Gastroparesis causes nausea, vomiting, and early satiety, often in diabetes. Biliary colic is episodic right upper quadrant pain after fatty meals, not chronic epigastric discomfort. Management includes reassurance, dietary advice, a proton pump inhibitor trial, and, if needed, a tricyclic antidepressant or prokinetic agent for refractory symptoms.', 'Medium', 24, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 65-year-old man reports epigastric pain, early satiety, and 9 kg of unintentional weight loss over 4 months. Examination shows a palpable left supraclavicular lymph node. He has a history of Helicobacter pylori infection. What is the most appropriate next step?', '["CT scan of the abdomen", "Barium study", "PET scan", "Tumor markers", "Upper endoscopy with biopsy"]'::jsonb, 4, 'Gastric adenocarcinoma, suggested by weight loss, early satiety, a Virchow node, and Helicobacter pylori as a risk factor, requires upper endoscopy with biopsy for tissue diagnosis. CT of the abdomen is used for staging after the diagnosis is established. A barium study cannot provide histology. A PET scan does not establish the diagnosis. Tumor markers are neither sensitive nor specific enough to diagnose gastric cancer. Other risk factors include smoking, a diet high in salted and smoked foods, and a family history, while linitis plastica is a diffuse infiltrative form with a poor prognosis.', 'Medium', 25, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 58-year-old man with a history of peptic ulcer disease reports vomiting undigested food for 2 weeks. Examination shows a succussion splash. Laboratory studies show hypochloremic, hypokalemic metabolic alkalosis. What is the most appropriate initial management?', '["Nasogastric decompression, intravenous fluids, and proton pump inhibitor", "Immediate surgery", "Endoscopy first", "Prokinetic agent", "CT scan of the abdomen"]'::jsonb, 0, 'Gastric outlet obstruction requires nasogastric decompression, intravenous fluid and electrolyte correction, and a proton pump inhibitor before definitive evaluation. The hypochloremic, hypokalemic metabolic alkalosis from vomiting must be corrected first. Surgery follows stabilization, not before resuscitation. Endoscopy is performed after decompression. Prokinetic agents worsen obstruction. CT of the abdomen delays resuscitation. Common causes include peptic ulcer scarring and gastric cancer, so endoscopy with biopsy is needed after stabilization to identify the underlying cause. Saline-responsive metabolic alkalosis is corrected with isotonic fluids and potassium replacement, and the patient is kept nil by mouth until decompression is achieved.', 'Hard', 26, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 40-year-old man presents with hematemesis after several episodes of forceful vomiting. Upper endoscopy shows a mucosal tear at the gastroesophageal junction without active bleeding. His vital signs are stable and hemoglobin is 13.5 g/dL. What is the most appropriate management?', '["Emergent surgery", "Endoscopic band ligation", "Supportive care with proton pump inhibitor", "Intravenous octreotide", "Transjugular intrahepatic portosystemic shunt"]'::jsonb, 2, 'Mallory-Weiss tears usually stop bleeding spontaneously, so supportive care with a proton pump inhibitor and observation is appropriate when there is no active bleeding. Emergent surgery is reserved for refractory bleeding. Endoscopic band ligation is used for esophageal varices, not mucosal tears. Intravenous octreotide is used for variceal bleeding. Transjugular intrahepatic portosystemic shunt is used for portal hypertension complications, not for a Mallory-Weiss tear. If bleeding persists, endoscopic clips or epinephrine injection can achieve hemostasis, and the tear typically heals within days. Most patients have a history of vomiting, retching, or coughing before the bleed.', 'Medium', 27, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 50-year-old man presents with severe chest pain after forceful vomiting. Examination shows subcutaneous emphysema in the neck and decreased breath sounds on the left. Chest radiograph shows pneumomediastinum and a left pleural effusion. What is the most appropriate next test?', '["Upper endoscopy", "Chest radiograph alone", "Proton pump inhibitor trial", "CT scan of the chest with oral contrast", "Thoracentesis"]'::jsonb, 3, 'Boerhaave syndrome, or spontaneous esophageal rupture after vomiting, requires CT of the chest with oral contrast, or a contrast esophagram, to confirm the leak and guide surgical repair. Upper endoscopy may worsen the perforation and should be avoided. A chest radiograph alone is insensitive for confirming a leak. A proton pump inhibitor does not treat a rupture. Thoracentesis drains the effusion but does not address the esophageal leak. The rupture is usually in the left posterolateral distal esophagus, and treatment is urgent surgery with broad-spectrum antibiotics and nothing by mouth.', 'Hard', 28, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 55-year-old man reports a chronic cough, hoarseness, and frequent throat clearing for 6 months, with heartburn twice weekly. Examination shows dental erosions and erythema of the posterior larynx. He does not smoke and has no dysphagia or weight loss. What is the most appropriate initial management?', '["Upper endoscopy", "Empiric proton pump inhibitor trial", "24-hour ambulatory pH monitoring", "Laryngoscopy", "Inhaled corticosteroids"]'::jsonb, 1, 'Extraesophageal gastroesophageal reflux disease, causing laryngitis, chronic cough, and dental erosions, is managed with an empiric proton pump inhibitor trial for 8 to 12 weeks. Upper endoscopy is reserved for alarm features or refractory symptoms. Ambulatory pH monitoring is used for refractory cases. Laryngoscopy does not confirm reflux. Inhaled corticosteroids treat asthma, not reflux laryngitis. Patients should also be counselled on weight loss, avoiding late meals, and elevating the head of the bed, since these measures reduce reflux and improve laryngeal symptoms. If symptoms persist despite therapy, referral to otolaryngology and pH-impedance testing are appropriate.', 'Medium', 29, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 45-year-old man has multiple duodenal ulcers refractory to proton pump inhibitor therapy and chronic watery diarrhea. His fasting serum gastrin is markedly elevated at 1200 pg/mL. What is the most appropriate next step to confirm the diagnosis?', '["Upper endoscopy", "Secretin stimulation test", "CT scan of the abdomen", "Helicobacter pylori testing", "Repeat fasting serum gastrin"]'::jsonb, 1, 'Zollinger-Ellison syndrome causes multiple refractory duodenal ulcers, diarrhea, and hypergastrinemia from a gastrin-secreting tumor. With fasting gastrin already markedly elevated, the secretin stimulation test confirms the diagnosis by showing a paradoxical rise in gastrin. Upper endoscopy shows ulcers but does not confirm the syndrome. CT of the abdomen localizes the gastrinoma after biochemical confirmation. Helicobacter pylori testing does not explain this syndrome. Repeating the fasting gastrin adds no new information. Most gastrinomas are in the gastrinoma triangle of the duodenum and pancreas, and high-dose proton pump inhibitors control acid hypersecretion while surgery is planned.', 'Hard', 30, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 28-year-old woman presents with a 3-month history of bloody diarrhea occurring 6 to 8 times daily, urgency, tenesmus, and crampy left lower quadrant pain. She has a low-grade fever and a 4-kg weight loss. Laboratory studies show a hemoglobin of 10.8 g/dL and an elevated C-reactive protein. Colonoscopy reveals continuous mucosal erythema, friability, and ulceration beginning in the rectum and extending to the splenic flexure, with loss of the normal vascular pattern. What is the most likely diagnosis?', '["Ulcerative colitis", "Crohn disease", "Infectious colitis", "Ischemic colitis", "Microscopic colitis"]'::jsonb, 0, 'Ulcerative colitis classically presents in a young adult with bloody diarrhea, urgency, tenesmus, and left-sided cramping, with continuous mucosal inflammation beginning in the rectum and extending proximally without skip areas, exactly as seen here. Crohn disease causes patchy, transmural inflammation with skip lesions, often involving the terminal ileum, and frequently produces fistulae, strictures, and perianal disease, none of which are present. Infectious colitis is usually acute and self-limited, often with a positive stool culture or a history of travel or recent antibiotics. Ischemic colitis typically affects older patients with vascular disease and presents with sudden pain followed by bloody stools. Microscopic colitis causes chronic watery, non-bloody diarrhea with a normal-appearing colonoscopy.', 'Medium', 31, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 34-year-old man with moderate-to-severe ulcerative colitis involving the entire colon has failed mesalamine and is now corticosteroid-dependent, flaring whenever prednisone is tapered below 20 mg daily. He has no signs of toxic megacolon, perforation, or dysplasia on recent colonoscopy. He is up to date on vaccinations and has a negative tuberculosis screen and hepatitis B panel. What is the most appropriate next step in management?', '["Continue prednisone 40 mg daily indefinitely", "Start infliximab, an anti-tumor necrosis factor agent", "Increase oral mesalamine to maximum dose", "Proceed directly to total colectomy", "Start azathioprine alone as monotherapy"]'::jsonb, 1, 'This patient has steroid-dependent moderate-to-severe ulcerative colitis, and the next step is escalation to a biologic agent such as the anti-tumor necrosis factor antibody infliximab, which induces and maintains remission and allows steroid withdrawal. Continuing prednisone indefinitely is inappropriate because long-term steroids cause osteoporosis, diabetes, infection, and adrenal suppression without maintaining remission. Increasing mesalamine is insufficient for moderate-to-severe disease that has already failed it. Total colectomy is reserved for medically refractory disease, dysplasia, or emergent complications, not as the next step when biologic therapy has not been tried. Azathioprine alone is slower in onset and less effective than anti-tumor necrosis factor therapy for induction in this setting.', 'Hard', 32, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 45-year-old man with a 10-year history of ulcerative colitis presents with severe bloody diarrhea, abdominal distension, fever of 38.9 C, heart rate 122/min, and a white blood cell count of 18,000/mm3. Abdominal examination shows marked distension with diminished bowel sounds and diffuse tenderness. Abdominal radiograph demonstrates colonic dilation of 7 cm with loss of haustration and mucosal islands. He has not had a recent colonoscopy. What is the most appropriate next step in management?', '["Start oral mesalamine and discharge home", "Perform a full colonoscopy to assess disease extent", "Admit for intravenous corticosteroids with urgent surgical consultation", "Give loperamide to control the diarrhea", "Start oral vancomycin for presumed Clostridioides difficile infection"]'::jsonb, 2, 'This patient has toxic megacolon, a life-threatening complication of severe ulcerative colitis defined by colonic dilation greater than 6 cm with systemic toxicity including fever, tachycardia, and leukocytosis. He requires admission, bowel rest, intravenous corticosteroids, correction of electrolytes, and urgent surgical consultation because perforation may require colectomy. Oral mesalamine and discharge are unsafe in a toxic patient with a dilated colon. Colonoscopy is contraindicated because insufflation markedly increases the risk of perforation in toxic megacolon. Loperamide worsens colonic dilation and is contraindicated. Although Clostridioides difficile testing should be sent, oral vancomycin alone does not treat the underlying toxic megacolon or the risk of perforation.', 'Hard', 33, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 22-year-old woman presents with a 6-month history of crampy right lower quadrant pain, non-bloody diarrhea, and a 6-kg weight loss. She reports a draining perianal lesion. Physical examination reveals a perianal fistula and right lower quadrant tenderness without rebound. Colonoscopy shows patchy areas of inflammation with deep linear ulcers and cobblestoning, with skip areas of normal mucosa between involved segments, and the terminal ileum is inflamed. Biopsy shows transmural inflammation with noncaseating granulomas. What is the most likely diagnosis?', '["Ulcerative colitis", "Irritable bowel syndrome", "Celiac disease", "Crohn disease", "Ischemic colitis"]'::jsonb, 3, 'Crohn disease is characterized by patchy, transmural inflammation with skip lesions that can involve any part of the gastrointestinal tract, most commonly the terminal ileum and colon, with deep ulcers, cobblestoning, noncaseating granulomas, and complications such as perianal fistulae, exactly as seen here. Ulcerative colitis causes continuous mucosal inflammation limited to the colon beginning in the rectum, without fistulae or small bowel involvement. Irritable bowel syndrome is a functional disorder without inflammation, weight loss, or fistulae. Celiac disease causes malabsorption with villous atrophy of the small bowel, not colonic skip lesions or perianal fistulae. Ischemic colitis is an acute vascular event in older patients, not a chronic transmural inflammatory disease in a young adult.', 'Medium', 34, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 40-year-old man with a 12-year history of ileocolonic Crohn disease presents with recurrent episodes of crampy abdominal pain, bloating, and vomiting after meals over the past 2 months. He has had no fever, bloody diarrhea, or weight loss. Abdominal examination shows mild distension without peritoneal signs. CT enterography demonstrates a 12-cm narrowed segment of the terminal ileum with prestenotic dilation and minimal mural enhancement. What is the most appropriate next step in management?', '["Start high-dose intravenous corticosteroids", "Proceed directly to surgical resection", "Start infliximab immediately", "Obtain magnetic resonance enterography to characterize the stricture", "Start broad-spectrum antibiotics for presumed abscess"]'::jsonb, 3, 'This patient has a fibrostenotic stricture of the terminal ileum, a common complication of longstanding Crohn disease. Magnetic resonance enterography distinguishes an inflammatory stricture, which may respond to medical therapy, from a fibrotic stricture, which requires endoscopic dilation or surgery, and it also maps the anatomy before any intervention. High-dose corticosteroids treat active inflammation but do not relieve a fixed fibrotic stricture and increase perforation risk. Immediate surgery is premature without characterizing the stricture and excluding an inflammatory component that might respond to therapy. Starting infliximab without imaging is inappropriate because a fibrotic stricture will not respond to biologics. There is no fever, leukocytosis, or fluid collection to suggest an abscess requiring antibiotics.', 'Hard', 35, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 30-year-old woman with Crohn disease involving the terminal ileum underwent an ileal resection 2 years ago. She now presents with severe right flank pain, hematuria, and nausea. Urinalysis shows red blood cells and calcium oxalate crystals. Noncontrast CT of the abdomen shows a 7-mm stone in the right ureter. She has no history of urinary tract infection or hyperparathyroidism. Which complication of her ileal disease most likely explains this finding?', '["Calcium oxalate nephrolithiasis from increased colonic oxalate absorption", "Uric acid nephrolithiasis from increased purine turnover", "Struvite stones from recurrent urinary tract infection", "Cystine stones from a hereditary transport defect", "Calcium phosphate stones from renal tubular acidosis"]'::jsonb, 0, 'Ileal disease or resection causes bile acid malabsorption, so unabsorbed bile acids increase colonic permeability and free fatty acids bind luminal calcium, leaving oxalate unbound and available for colonic absorption, which produces hyperoxaluria and calcium oxalate kidney stones. Uric acid stones result from high purine turnover or acidic urine in conditions such as gout or myeloproliferative disorders, not ileal disease. Struvite stones form in the setting of recurrent urinary tract infection with urease-producing organisms, which this patient does not have. Cystine stones are caused by an inherited defect in renal cystine transport and are unrelated to Crohn disease. Calcium phosphate stones are associated with renal tubular acidosis and alkaline urine, not with ileal resection.', 'Hard', 36, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 26-year-old woman presents with a 2-year history of recurrent crampy lower abdominal pain that improves after defecation and is associated with a change in stool frequency and form, alternating between loose stools and constipation. She has no weight loss, nocturnal symptoms, fever, or blood in the stool. Physical examination is normal. Complete blood count, thyroid-stimulating hormone, celiac serology, and stool studies are all normal. Colonoscopy performed 6 months ago was normal. What is the most likely diagnosis?', '["Inflammatory bowel disease", "Irritable bowel syndrome, mixed type", "Microscopic colitis", "Colorectal cancer", "Small intestinal bacterial overgrowth"]'::jsonb, 1, 'This patient meets the Rome IV criteria for irritable bowel syndrome: recurrent abdominal pain at least one day per week for three months, related to defecation and associated with a change in stool frequency and form, with no alarm features and normal laboratory and endoscopic evaluation. Her alternating diarrhea and constipation fit the mixed subtype. Inflammatory bowel disease would cause inflammation with elevated inflammatory markers, bloody diarrhea, weight loss, or abnormal endoscopy. Microscopic colitis typically causes chronic watery non-bloody diarrhea in older adults and requires colonic biopsies for diagnosis. Colorectal cancer would produce alarm features such as weight loss, anemia, or blood in the stool. Small intestinal bacterial overgrowth causes bloating and malabsorption but does not explain this classic pain-defecation pattern.', 'Medium', 37, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 55-year-old man with a 3-year history of intermittent abdominal cramping and alternating diarrhea and constipation, previously labeled as irritable bowel syndrome, now reports a 7-kg unintentional weight loss over 4 months, nocturnal diarrhea that wakes him from sleep, and blood mixed in the stool. Laboratory studies show a hemoglobin of 10.2 g/dL and a ferritin of 12 ng/mL. What is the most appropriate next step in management?', '["Reassure and continue a low-FODMAP diet", "Start loperamide and a tricyclic antidepressant", "Perform a colonoscopy", "Order a hydrogen breath test", "Start a trial of rifaximin"]'::jsonb, 2, 'This patient has multiple alarm features that are incompatible with irritable bowel syndrome: age over 50 with new symptoms, unintentional weight loss, nocturnal diarrhea, hematochezia, and iron deficiency anemia. These red flags mandate direct visualization of the colon to exclude colorectal cancer, inflammatory bowel disease, or other organic pathology, so colonoscopy is the appropriate next step. Reassurance and a low-FODMAP diet would delay diagnosis of a potentially malignant or inflammatory cause. Loperamide and tricyclic antidepressants are symptomatic treatments for irritable bowel syndrome and do not address the underlying alarm features. A hydrogen breath test evaluates for small intestinal bacterial overgrowth or carbohydrate malabsorption, which does not explain blood loss and weight loss. Rifaximin is used for irritable bowel syndrome with diarrhea, not for evaluating alarm features.', 'Medium', 38, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 32-year-old woman with irritable bowel syndrome with diarrhea reports that her symptoms are triggered by onions, garlic, beans, and wheat. She has no alarm features, and her laboratory studies and colonoscopy are normal. She has tried increasing dietary fiber without benefit. What is the most appropriate initial management?', '["Start daily alosetron", "Begin a structured low-FODMAP diet with dietitian guidance", "Start rifaximin 550 mg three times daily", "Start amitriptyline 50 mg nightly", "Repeat colonoscopy with random biopsies"]'::jsonb, 3, 'This patient''s symptoms are clearly triggered by high-FODMAP foods such as onions, garlic, beans, and wheat, which are fermented by colonic bacteria and cause gas, bloating, and diarrhea. A structured low-FODMAP diet with dietitian guidance is an effective first-line dietary intervention for irritable bowel syndrome with diarrhea and directly addresses her identified triggers. Alosetron is a 5-HT3 antagonist reserved for severe refractory diarrhea-predominant disease in women because of the risk of ischemic colitis. Rifaximin is used for moderate-to-severe symptoms that have not responded to dietary measures, not as initial therapy. Amitriptyline is a neuromodulator for refractory pain-predominant disease, not first-line for dietary-triggered diarrhea. Repeat colonoscopy is unnecessary because her recent colonoscopy was normal and she has no alarm features.', 'Medium', 39, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 24-year-old woman presents with a 1-year history of chronic diarrhea, abdominal bloating, and a 5-kg weight loss. She has iron deficiency anemia refractory to oral iron and an itchy, blistering rash on her elbows and knees. Laboratory studies show a markedly elevated tissue transglutaminase IgA antibody while she is eating a regular diet containing gluten. Her total serum IgA level is normal. What is the most appropriate next step to confirm the diagnosis?', '["Start a gluten-free diet and observe the response", "Measure anti-gliadin antibodies", "Perform an upper endoscopy with duodenal biopsies", "Order a hydrogen breath test", "Perform a colonoscopy with terminal ileum intubation"]'::jsonb, 4, 'This patient has the classic presentation of celiac disease with chronic diarrhea, malabsorption, refractory iron deficiency anemia, and dermatitis herpetiformis, and a markedly positive tissue transglutaminase IgA while consuming gluten is highly sensitive and specific. However, the diagnosis should be confirmed with upper endoscopy and duodenal biopsies showing villous atrophy, crypt hyperplasia, and increased intraepithelial lymphocytes before committing the patient to a lifelong gluten-free diet. Starting a gluten-free diet before biopsy would heal the mucosa and make histologic confirmation impossible. Anti-gliadin antibodies are less sensitive and specific than tissue transglutaminase IgA and add nothing here. A hydrogen breath test evaluates carbohydrate malabsorption, not celiac disease. Colonoscopy does not assess the duodenum, where celiac disease causes its characteristic injury.', 'Medium', 40, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 30-year-old man with biopsy-confirmed celiac disease has followed a gluten-free diet for 1 year but reports ongoing intermittent diarrhea and bloating. His tissue transglutaminase IgA level remains elevated. He denies intentional gluten intake but eats frequently at restaurants and consumes processed sauces and soups. Repeat duodenal biopsy shows persistent villous atrophy. What is the most likely explanation for his persistent symptoms?', '["Refractory celiac disease", "Inadvertent gluten ingestion", "Small intestinal bacterial overgrowth", "Lactose intolerance", "Exocrine pancreatic insufficiency"]'::jsonb, 1, 'Persistent symptoms in a patient with celiac disease who reports adherence to a gluten-free diet are most often caused by inadvertent gluten ingestion, which is extremely common because gluten is present in sauces, processed foods, and cross-contaminated products. Serologic monitoring with tissue transglutaminase IgA and careful dietitian review usually identify ongoing exposure. Refractory celiac disease is a diagnosis of exclusion requiring persistent villous atrophy despite a strictly gluten-free diet for at least 12 months and is uncommon. Small intestinal bacterial overgrowth and lactose intolerance can cause similar symptoms but are less common than ongoing gluten exposure. Exocrine pancreatic insufficiency causes steatorrhea and is not a typical cause of persistent symptoms in treated celiac disease.', 'Medium', 41, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 58-year-old woman with a 30-year history of untreated celiac disease, never having followed a gluten-free diet, presents with a 10-kg weight loss, night sweats, fever, and abdominal pain. Physical examination reveals generalized lymphadenopathy and a palpable abdominal mass. Laboratory studies show a hemoglobin of 9.4 g/dL and a markedly elevated lactate dehydrogenase. CT of the abdomen shows thickened loops of small bowel with enlarged mesenteric lymph nodes. What is the most likely diagnosis?', '["Small bowel adenocarcinoma", "Refractory celiac disease", "Enteropathy-associated T-cell lymphoma", "Autoimmune thyroid disease", "Dermatitis herpetiformis"]'::jsonb, 2, 'Longstanding untreated celiac disease carries an increased risk of enteropathy-associated T-cell lymphoma, a rare but aggressive malignancy that typically presents with weight loss, night sweats, abdominal pain, lymphadenopathy, and refractory malabsorption despite a gluten-free diet. This patient''s B symptoms with lymphadenopathy after decades of untreated disease are highly concerning for this complication. Small bowel adenocarcinoma is also associated with celiac disease but less commonly presents with systemic B symptoms and generalized lymphadenopathy. Refractory celiac disease causes persistent villous atrophy and malabsorption but not fever, night sweats, and lymphadenopathy. Autoimmune thyroid disease is a common associated condition but does not explain these findings. Dermatitis herpetiformis is the skin manifestation of celiac disease, not a cause of B symptoms and lymphadenopathy.', 'Hard', 42, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 62-year-old woman presents with a 3-day history of left lower quadrant pain, fever, and anorexia. She is hemodynamically stable with a temperature of 38.4 C, a white blood cell count of 13,500/mm3, and localized left lower quadrant tenderness without peritoneal signs. CT of the abdomen shows sigmoid colonic wall thickening with pericolic fat stranding and a 2-cm pericolic fluid collection consistent with a small abscess. What is the most appropriate management?', '["Admit for intravenous antibiotics and bowel rest", "Perform percutaneous drainage of the abscess", "Proceed to sigmoid colectomy", "Perform urgent colonoscopy to exclude malignancy", "Start outpatient oral antibiotics with a clear liquid diet"]'::jsonb, 4, 'This patient has uncomplicated acute diverticulitis with a small pericolic abscess, and current guidelines support outpatient management with oral antibiotics covering gram-negative organisms and anaerobes plus a clear liquid diet, provided the patient is hemodynamically stable, tolerates oral intake, and has reliable follow-up. Intravenous antibiotics and admission are reserved for complicated disease, immunocompromised patients, or inability to tolerate oral therapy. Percutaneous drainage is indicated for a larger abscess, typically greater than 3 to 4 cm, not a 2-cm collection. Surgical resection is reserved for perforation with peritonitis, refractory disease, or recurrent complicated episodes. Colonoscopy is contraindicated during acute diverticulitis because insufflation increases perforation risk and should be performed 6 to 8 weeks later to exclude cancer.', 'Medium', 43, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 70-year-old man with known sigmoid diverticulosis presents with sudden severe abdominal pain, rigidity, fever of 39.1 C, heart rate 128/min, and blood pressure 88/54 mmHg. Abdominal examination shows a rigid abdomen with diffuse rebound tenderness and absent bowel sounds. CT of the abdomen demonstrates free intraperitoneal air and a large amount of free fluid. What is the most appropriate next step in management?', '["Intravenous antibiotics alone", "Percutaneous drainage of the abscess", "Urgent colonoscopy", "Discharge home with oral antibiotics", "Emergent surgical intervention with sigmoid resection and colostomy"]'::jsonb, 4, 'Free intraperitoneal air with peritonitis indicates perforated diverticulitis with fecal contamination, a surgical emergency requiring immediate operative management, typically a Hartmann procedure with sigmoid resection and end colostomy in an unstable or severely contaminated patient. Intravenous antibiotics alone cannot control ongoing fecal contamination of the peritoneum. Percutaneous drainage is appropriate for a contained abscess but not for free perforation with generalized peritonitis. Colonoscopy is contraindicated in acute perforated diverticulitis because insufflation would worsen contamination. Discharge with oral antibiotics would be dangerous and is appropriate only for uncomplicated diverticulitis in a stable patient without perforation or peritonitis.', 'Medium', 44, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 68-year-old man presents with a sudden episode of painless, large-volume bright red blood per rectum. He has no abdominal pain, fever, or diarrhea. His blood pressure is 110/70 mmHg and heart rate is 92/min. Hemoglobin is 9.1 g/dL, down from 13.5 g/dL one month ago. He has a history of sigmoid diverticulosis. Colonoscopy after bowel preparation shows multiple diverticula in the sigmoid colon with a visible vessel and stigmata of recent bleeding in one diverticulum. What is the most likely source of bleeding?', '["Diverticular bleeding", "Angiodysplasia", "Ischemic colitis", "Inflammatory bowel disease", "Hemorrhoidal bleeding"]'::jsonb, 0, 'Diverticular bleeding is the most common cause of acute lower gastrointestinal bleeding in older adults and classically presents as painless, large-volume hematochezia in a patient with known diverticulosis. Angiodysplasia also causes painless bleeding but typically produces chronic, low-grade, intermittent blood loss rather than a single large-volume episode, and it is associated with aortic stenosis and end-stage renal disease. Ischemic colitis causes abdominal pain followed by bloody diarrhea in older patients with vascular disease. Inflammatory bowel disease causes bloody diarrhea with abdominal pain and systemic symptoms. Hemorrhoidal bleeding is usually small-volume bright red blood seen on toilet paper or coating the stool, not large-volume hematochezia requiring transfusion.', 'Medium', 45, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 50-year-old man with no family history of colorectal cancer or polyps, no inflammatory bowel disease, and no prior colorectal screening asks about colorectal cancer screening. He has no symptoms, takes no medications, and has no personal history of adenomas. What is the most appropriate screening recommendation?', '["Annual fecal immunochemical testing only", "Colonoscopy every 10 years", "Flexible sigmoidoscopy every 5 years", "Fecal immunochemical testing every 3 years", "CT colonography every 5 years"]'::jsonb, 1, 'Average-risk colorectal cancer screening begins at age 45 according to current guidelines, and colonoscopy every 10 years is the preferred strategy because it both detects and removes precancerous polyps. Annual fecal immunochemical testing is an acceptable alternative but requires yearly testing and colonoscopy if positive. Flexible sigmoidoscopy every 5 years examines only the distal colon and misses right-sided lesions. A single fecal immunochemical test every 3 years is not a recommended interval, since stool-based testing must be performed annually to be effective. CT colonography every 5 years is an alternative for patients who decline colonoscopy, but it cannot remove polyps and requires bowel preparation and radiation exposure.', 'Easy', 46, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 35-year-old man undergoes colonoscopy for rectal bleeding and is found to have more than 100 adenomatous polyps throughout the colon. His father died of colorectal cancer at age 38, and his paternal grandfather also had colon cancer in his 30s. Upper endoscopy reveals duodenal adenomas. Genetic testing is pending. What is the most likely diagnosis?', '["Lynch syndrome", "Peutz-Jeghers syndrome", "Familial adenomatous polyposis", "Juvenile polyposis syndrome", "MUTYH-associated polyposis"]'::jsonb, 2, 'Familial adenomatous polyposis is an autosomal dominant syndrome caused by a germline mutation in the APC tumor suppressor gene and is characterized by hundreds to thousands of colorectal adenomas beginning in adolescence, with an essentially 100 percent lifetime risk of colorectal cancer by age 40 if the colon is not removed. The presence of more than 100 polyps in a young patient with a strong family history is diagnostic. Lynch syndrome causes fewer polyps and early-onset cancer with mismatch repair deficiency, not hundreds of adenomas. Peutz-Jeghers syndrome causes hamartomatous polyps with mucocutaneous pigmentation. Juvenile polyposis syndrome causes hamartomatous polyps in childhood. MUTYH-associated polyposis is autosomal recessive and typically produces 10 to 100 polyps, far fewer than seen here.', 'Hard', 47, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 42-year-old woman is diagnosed with right-sided colon cancer and is found to have had endometrial cancer at age 38. Her mother died of colon cancer at age 45, and her sister had ovarian cancer at age 40. Tumor testing shows high microsatellite instability with loss of MSH2 protein expression on immunohistochemistry. What is the most appropriate next step to confirm the underlying hereditary syndrome?', '["APC gene mutation testing", "KRAS mutation testing of the tumor", "Stool DNA testing", "Germline testing for DNA mismatch repair genes", "CT colonography"]'::jsonb, 3, 'Lynch syndrome is an autosomal dominant condition caused by germline mutations in DNA mismatch repair genes such as MLH1, MSH2, MSH6, and PMS2, and it predisposes to early-onset colorectal cancer and extracolonic cancers, most notably endometrial cancer. A tumor showing high microsatellite instability or loss of mismatch repair protein expression in a young patient with synchronous or metachronous colorectal and endometrial cancers is highly suggestive. Genetic testing for mismatch repair gene mutations confirms the diagnosis and enables cascade testing and surveillance of relatives. APC mutations cause familial adenomatous polyposis with hundreds of polyps, not this pattern. KRAS testing guides chemotherapy selection, not hereditary diagnosis. Stool DNA testing is a screening tool, not a diagnostic test for hereditary syndromes. CT colonography is an imaging alternative, not a genetic diagnostic test.', 'Hard', 48, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 25-year-old man returns from a 2-week trip to Mexico, where he drank tap water and ate street food. Three days after arrival he developed profuse watery diarrhea, crampy abdominal pain, and mild nausea without fever or blood in the stool. He is afebrile with normal vital signs and mild dehydration on examination. Stool studies are negative for blood and leukocytes. What is the most likely causative organism?', '["Campylobacter jejuni", "Shigella dysenteriae", "Salmonella enterica", "Entamoeba histolytica", "Enterotoxigenic Escherichia coli"]'::jsonb, 4, 'Traveler''s diarrhea is most commonly caused by enterotoxigenic Escherichia coli, which produces heat-labile and heat-stable enterotoxins that cause profuse watery diarrhea without fever or blood. The incubation period of 1 to 3 days after arrival in an endemic area, watery non-bloody diarrhea, and crampy abdominal pain are classic. Campylobacter typically causes bloody diarrhea with fever and severe abdominal pain. Shigella causes dysentery with blood and mucus, fever, and tenesmus. Salmonella causes gastroenteritis with fever and diarrhea after contaminated food. Entamoeba histolytica causes dysentery with bloody stools and can produce liver abscess, not acute watery traveler''s diarrhea.', 'Medium', 49, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'An 8-year-old boy presents with a 2-day history of bloody diarrhea, severe abdominal cramps, and vomiting after eating an undercooked hamburger at a family barbecue. He is afebrile with mild dehydration. Laboratory studies show a hemoglobin of 11.8 g/dL, platelets of 220,000/mm3, and a normal creatinine. Stool studies show bloody stool with leukocytes. What is the most appropriate management?', '["Supportive care with hydration and avoidance of antibiotics", "Azithromycin", "Ciprofloxacin", "Stool culture alone without treatment", "Urgent colonoscopy"]'::jsonb, 0, 'Enterohemorrhagic Escherichia coli O157:H7 causes bloody diarrhea with severe abdominal cramps and little fever after ingestion of undercooked ground beef. Antibiotics should be avoided because they increase the risk of hemolytic uremic syndrome by promoting Shiga toxin release, so management is supportive with hydration and close monitoring for hemolytic uremic syndrome. Azithromycin is appropriate for traveler''s diarrhea or Campylobacter but not for Shiga toxin-producing E. coli. Ciprofloxacin is contraindicated for the same reason and also carries risks of resistance and Clostridioides difficile infection. Stool culture is useful for diagnosis but is not the management priority. Colonoscopy is not indicated in acute infectious bloody diarrhea and increases perforation risk.', 'Medium', 50, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 30-year-old man presents with a 3-week history of watery diarrhea, bloating, excessive flatulence, and foul-smelling greasy stools. He has no fever or blood in the stool. He recently returned from a hiking trip during which he drank untreated stream water. Stool microscopy shows flagellated trophozoites with a characteristic falling-leaf motility and cysts with two nuclei. What is the most likely causative organism?', '["Entamoeba histolytica", "Giardia lamblia", "Cryptosporidium parvum", "Cyclospora cayetanensis", "Norovirus"]'::jsonb, 1, 'Giardia lamblia is a flagellated protozoan acquired by drinking contaminated water during hiking or camping, and it causes prolonged watery diarrhea, bloating, flatulence, and foul-smelling greasy stools without blood or fever, often lasting weeks. The organism adheres to the duodenal mucosa and causes malabsorption. Entamoeba histolytica causes dysentery with bloody stools and liver abscess, not foul-smelling watery diarrhea. Cryptosporidium causes self-limited watery diarrhea, typically in immunocompromised hosts or after exposure to recreational water, and is resistant to chlorine. Cyclospora causes prolonged watery diarrhea after ingestion of contaminated produce. Norovirus causes acute vomiting-predominant illness with a short duration, not weeks of foul-smelling diarrhea with malabsorption.', 'Medium', 51, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 72-year-old woman who received a 10-day course of clindamycin for a dental infection 2 weeks ago now presents with profuse watery diarrhea occurring 10 times daily, lower abdominal cramping, and a low-grade fever. Laboratory studies show a white blood cell count of 16,000/mm3 and a creatinine of 1.4 mg/dL. She is hemodynamically stable. What is the most appropriate initial diagnostic test?', '["Stool culture for Clostridioides difficile", "Single toxin enzyme immunoassay alone", "Stool nucleic acid amplification testing for toxin genes", "Colonoscopy with biopsy", "Serum lactate and abdominal CT"]'::jsonb, 2, 'Clostridioides difficile infection should be suspected in a patient with watery diarrhea after recent antibiotic exposure, particularly clindamycin, fluoroquinolones, or cephalosporins, and the diagnosis is confirmed by stool testing for the toxin genes using nucleic acid amplification testing or a two-step algorithm of glutamate dehydrogenase plus toxin enzyme immunoassay. A single toxin enzyme immunoassay alone has lower sensitivity and is no longer recommended as a standalone test. Stool culture is slow and not used for clinical diagnosis. Colonoscopy is not the diagnostic test of choice and is reserved for cases where stool testing is unavailable and pseudomembranous colitis is suspected, because it carries a perforation risk. Serum lactate and abdominal imaging assess severity but do not establish the diagnosis.', 'Medium', 52, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 65-year-old man with a history of hypertension presents with watery diarrhea 8 times daily, abdominal cramping, and a white blood cell count of 14,000/mm3 after a recent course of ceftriaxone for pneumonia. He is hemodynamically stable with a normal creatinine and lactate. Stool nucleic acid amplification testing is positive for Clostridioides difficile toxin genes. What is the most appropriate treatment?', '["Oral metronidazole", "Oral vancomycin", "Intravenous vancomycin", "Fidaxomicin", "Fecal microbiota transplantation"]'::jsonb, 3, 'Fidaxomicin is now the preferred first-line treatment for an initial episode of nonfulminant Clostridioides difficile infection because it has a lower recurrence rate than oral vancomycin while achieving similar cure rates, reflecting its narrower spectrum and preservation of normal gut flora. Oral vancomycin remains an acceptable alternative when fidaxomicin is unavailable. Metronidazole is no longer recommended as first-line therapy because of inferior efficacy and higher recurrence. Intravenous vancomycin does not achieve adequate colonic concentrations and is ineffective. Fecal microbiota transplantation is reserved for recurrent or fulminant disease, not for an initial nonsevere episode. Discontinuing the inciting antibiotic and providing supportive care alone are insufficient for symptomatic infection.', 'Hard', 53, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 78-year-old man with a recent history of broad-spectrum antibiotic use presents with profuse watery diarrhea, severe abdominal distension, hypotension with a blood pressure of 88/52 mmHg, and a heart rate of 124/min. Laboratory studies show a white blood cell count of 35,000/mm3, creatinine of 2.8 mg/dL, and lactate of 4.6 mmol/L. Abdominal radiograph shows colonic dilation of 8 cm with thumbprinting. Stool testing is positive for Clostridioides difficile toxin. What is the most appropriate management?', '["Oral vancomycin alone", "Metronidazole alone", "Discontinue all antibiotics and observe", "Fecal microbiota transplantation", "High-dose oral vancomycin plus intravenous metronidazole with urgent surgical evaluation"]'::jsonb, 4, 'Fulminant Clostridioides difficile infection is defined by hypotension, shock, ileus, or megacolon, and this patient has hypotension, a markedly elevated lactate, a white blood cell count of 35,000/mm3, and colonic dilation, all indicating life-threatening disease. Management requires high-dose oral vancomycin plus intravenous metronidazole, aggressive supportive care, and urgent surgical evaluation because subtotal colectomy with end ileostomy may be life-saving. Oral vancomycin alone is insufficient for fulminant disease. Metronidazole alone has poor efficacy and is not adequate. Discontinuing antibiotics alone will not reverse fulminant colitis. Fecal microbiota transplantation is not the first-line treatment for fulminant disease and is considered only in selected cases when surgery is not an option or after stabilization.', 'Hard', 54, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 74-year-old man presents with bright red blood per rectum for 6 hours. He is hemodynamically stable with a blood pressure of 126/78 mmHg and heart rate of 88/min. Hemoglobin is 10.6 g/dL, down from 13.2 g/dL last month. He has no abdominal pain, fever, or diarrhea. He takes aspirin for coronary artery disease. Rectal examination shows bright red blood. What is the most appropriate next step in the evaluation of this patient?', '["Colonoscopy after bowel preparation", "CT angiography", "Upper endoscopy", "Tagged red blood cell scan", "Discharge home with oral iron supplementation"]'::jsonb, 0, 'A hemodynamically stable patient with acute lower gastrointestinal bleeding should undergo colonoscopy after adequate bowel preparation, which allows both diagnosis and therapeutic intervention such as clipping or coagulation of a bleeding diverticulum or angiodysplastic lesion. CT angiography is reserved for brisk, ongoing bleeding in an unstable patient or when colonoscopy cannot localize the source. Upper endoscopy evaluates upper gastrointestinal bleeding and is not the first test for hematochezia, although it is considered when the bleeding source is unclear. A tagged red blood cell scan is a slower, less sensitive localization study used when bleeding is intermittent. Discharge with iron supplementation is inappropriate for acute hematochezia with a significant hemoglobin drop, as the bleeding source must be identified and treated.', 'Medium', 55, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'An 80-year-old man on warfarin for atrial fibrillation presents with brisk bright red blood per rectum, lightheadedness, a blood pressure of 92/58 mmHg, and a heart rate of 118/min. He has required 3 units of packed red blood cells in the past 4 hours. His INR is 3.4. Despite holding warfarin and aggressive fluid resuscitation, he continues to pass large amounts of bright red blood. What is the most appropriate next step in management?', '["Urgent colonoscopy", "CT angiography to localize the bleeding source", "Upper endoscopy", "Tagged red blood cell scan", "Discharge home with close follow-up"]'::jsonb, 1, 'This patient has brisk, ongoing lower gastrointestinal bleeding with hemodynamic instability and transfusion requirements despite resuscitation, so the priority is localization of the bleeding source with CT angiography, which can detect active extravasation at rates as low as 0.3 mL/min and guide embolization or surgery. Colonoscopy is not feasible in an actively bleeding, unstable patient with unprepared bowel and would delay definitive management. Upper endoscopy is indicated when the source of hematochezia is unclear because brisk upper gastrointestinal bleeding can present with hematochezia, but it is not the first test once the bleeding is known to be ongoing and lower. A tagged red blood cell scan is slower and less sensitive than CT angiography for brisk bleeding. Discharging the patient would be dangerous given ongoing transfusion requirements and instability.', 'Hard', 56, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 24-year-old man presents with painless, large-volume bright red blood per rectum. He has no abdominal pain, fever, diarrhea, or weight loss. Physical examination and anoscopy are normal. Hemoglobin is 11.4 g/dL. Colonoscopy and upper endoscopy are both normal. A technetium-99m pertechnetate scan is performed. What is the most likely diagnosis?', '["Diverticular bleeding", "Angiodysplasia", "Meckel diverticulum", "Inflammatory bowel disease", "Hemorrhoidal bleeding"]'::jsonb, 2, 'Meckel diverticulum is the most common congenital anomaly of the gastrointestinal tract, resulting from persistence of the vitelline duct, and it is the classic cause of painless lower gastrointestinal bleeding in children and young adults because ectopic gastric mucosa within the diverticulum secretes acid that ulcerates adjacent ileal mucosa. The technetium-99m pertechnetate scan detects ectopic gastric mucosa and confirms the diagnosis. Diverticular bleeding is the leading cause of lower gastrointestinal bleeding in older adults, not young adults. Angiodysplasia typically affects patients over 60 years of age and causes chronic intermittent bleeding. Inflammatory bowel disease causes bloody diarrhea with abdominal pain and systemic symptoms. Hemorrhoids cause small-volume bright red blood with defecation, not large-volume painless hematochezia in a young adult.', 'Hard', 57, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 45-year-old man presents with painless bright red blood on the toilet paper and in the toilet bowl after bowel movements for the past 2 months. He reports perianal itching and a sensation of incomplete evacuation. He has no abdominal pain, weight loss, or change in bowel habits. Physical examination shows grade II internal hemorrhoids that prolapse with straining and reduce spontaneously. His hemoglobin is normal. What is the most appropriate initial management?', '["Rubber band ligation", "Hemorrhoidectomy", "Topical nitroglycerin", "Conservative management with increased dietary fiber, hydration, and sitz baths", "Urgent colonoscopy"]'::jsonb, 3, 'Internal hemorrhoids are the most common cause of painless bright red blood with defecation, often described as blood on the toilet paper or in the toilet bowl, with associated itching and a sensation of incomplete evacuation. First-line management is conservative: increased dietary fiber, adequate hydration, avoidance of straining, and sitz baths, which reduce symptoms in most patients. Rubber band ligation is reserved for grade II or III hemorrhoids that fail conservative therapy. Hemorrhoidectomy is reserved for severe or refractory disease. Topical nitroglycerin is the treatment for anal fissure, not hemorrhoids, and is used to reduce internal sphincter spasm. Colonoscopy would be indicated if there were alarm features such as age over 45 without prior screening, weight loss, or change in bowel habits, but not as the first step for classic hemorrhoidal bleeding in this patient.', 'Medium', 58, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 30-year-old woman presents with severe sharp pain during and after bowel movements for the past 3 weeks, with small amounts of bright red blood on the toilet paper. She has no diarrhea, weight loss, or fever. Physical examination shows a linear tear at the posterior midline of the anus with a small sentinel skin tag. She has tried increasing dietary fiber and taking sitz baths for 2 weeks without improvement. What is the most appropriate next step in management?', '["Lateral internal sphincterotomy", "Rubber band ligation", "Urgent colonoscopy", "Conservative management with fiber and sitz baths alone", "Topical calcium channel blocker with continued fiber and sitz baths"]'::jsonb, 4, 'An acute anal fissure presents with severe sharp pain during and after defecation, bright red blood on the toilet paper, and a visible linear tear at the posterior midline, often with a sentinel skin tag. First-line therapy is conservative: increased dietary fiber, adequate hydration, and warm sitz baths to soften stools and reduce trauma. Topical calcium channel blockers such as nifedipine or diltiazem, or topical nitrates, reduce internal sphincter spasm and promote healing, and are the next step when conservative measures are insufficient. Lateral internal sphincterotomy is reserved for chronic fissures refractory to medical therapy. Rubber band ligation treats internal hemorrhoids, not fissures. Colonoscopy is not the first step for a classic anal fissure without alarm features or a need for colorectal cancer screening.', 'Medium', 59, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 38-year-old man presents with 3 days of severe constant perianal pain, fever of 38.6 C, and difficulty sitting. Physical examination shows a tender, fluctuant, erythematous 3-cm mass at the right perianal region with surrounding induration. He has no diarrhea, rectal bleeding, or history of inflammatory bowel disease. What is the most appropriate management?', '["Incision and drainage", "Antibiotics alone", "Warm sitz baths and increased dietary fiber", "Topical corticosteroids", "Urgent colonoscopy"]'::jsonb, 0, 'A perianal abscess presents with severe constant perianal pain, fever, and a tender, fluctuant, erythematous mass near the anus, and the definitive treatment is prompt incision and drainage, which relieves pain and prevents progression to a fistula or sepsis. Antibiotics alone are insufficient because an abscess is a walled-off collection that requires drainage, and they are used only as adjuncts in patients with cellulitis, diabetes, or immunosuppression. Warm sitz baths and fiber provide symptomatic relief but do not treat the abscess. Topical steroids have no role in abscess management and may worsen infection. Colonoscopy is not indicated for an acute perianal abscess and would delay definitive drainage; it is reserved for evaluating underlying Crohn disease in patients with recurrent or complex perianal disease.', 'Medium', 60, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 24-year-old man presents with 5 days of fever, malaise, nausea, and jaundice after returning from a trip to Mexico 3 weeks ago. He has dark urine and pale stools. Labs show ALT 1450 U/L, AST 980 U/L, total bilirubin 6.2 mg/dL, and alkaline phosphatase mildly elevated. IgM anti-hepatitis A virus antibody is positive. What is the most likely diagnosis?', '["Acute hepatitis A infection", "Acute hepatitis B infection", "Acute hepatitis E infection", "Alcoholic hepatitis", "Autoimmune hepatitis"]'::jsonb, 0, 'Hepatitis A is transmitted by the fecal-oral route with an incubation period of 2 to 6 weeks, and it typically causes a self-limited acute hepatitis with markedly elevated transaminases and cholestasis; IgM anti-HAV is diagnostic of acute infection. Acute hepatitis B would show HBsAg and IgM anti-HBc rather than IgM anti-HAV. Hepatitis E causes a similar illness but is more common after travel to South Asia and is particularly dangerous in pregnancy; serology would show IgM anti-HEV. Alcoholic hepatitis requires heavy alcohol use and typically shows an AST to ALT ratio greater than 2:1 with AST usually below 300 U/L. Autoimmune hepatitis is a chronic disease with positive antinuclear and anti-smooth muscle antibodies and hypergammaglobulinemia, not an acute febrile illness after travel.', 'Easy', 61, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 32-year-old woman undergoes routine health screening. She is asymptomatic with normal liver enzymes. Serology shows HBsAg positive, anti-HBs negative, anti-HBc IgG positive, HBeAg negative, anti-HBe positive, and HBV DNA 800 IU/mL. What is the most likely interpretation of these results?', '["Acute hepatitis B infection", "Chronic hepatitis B, inactive carrier phase", "Resolved hepatitis B infection", "Immunity from hepatitis B vaccination", "Hepatitis B window period"]'::jsonb, 1, 'Persistent HBsAg defines chronic hepatitis B infection, and anti-HBc IgG indicates past or chronic infection. The inactive carrier phase is characterized by HBeAg negativity, anti-HBe positivity, low HBV DNA, and normal ALT, which matches this patient. Acute hepatitis B would show IgM anti-HBc with markedly elevated ALT. Resolved infection requires loss of HBsAg with appearance of anti-HBs. Vaccination produces anti-HBs alone without anti-HBc. The window period shows isolated IgM anti-HBc with negative HBsAg and negative anti-HBs, which is not the pattern here.', 'Medium', 62, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 54-year-old man is found to have chronic hepatitis C infection, genotype 1a, with detectable HCV RNA. He has no cirrhosis, transient elastography shows F1 fibrosis, and he has never received antiviral therapy. He has no other medical problems. What is the most appropriate treatment?', '["Pegylated interferon plus ribavirin for 48 weeks", "Entecavir daily", "Glecaprevir-pibrentasvir for 8 weeks", "Observation without treatment since he has no cirrhosis", "Prednisone daily"]'::jsonb, 2, 'Direct-acting antivirals are first-line therapy for hepatitis C, and pangenotypic regimens such as glecaprevir-pibrentasvir achieve sustained virologic response rates above 95 percent with an 8-week course in treatment-naive patients without cirrhosis. Interferon-based therapy is obsolete because of poor efficacy and significant toxicity. Entecavir is an antiviral for hepatitis B, not hepatitis C. Observation is inappropriate because treatment prevents progression to cirrhosis and hepatocellular carcinoma and reduces transmission even in the absence of cirrhosis. Prednisone has no role in hepatitis C and can worsen viral replication.', 'Medium', 63, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 48-year-old man with a 20-year history of heavy alcohol use presents with jaundice, fever, and tender hepatomegaly. Labs show total bilirubin 12 mg/dL, INR 2.1, AST 240 U/L, ALT 90 U/L, and creatinine 1.0 mg/dL. His Maddrey discriminant function is 45. Blood cultures and diagnostic paracentesis show no infection. What is the most appropriate next step in management?', '["N-acetylcysteine infusion", "Ursodeoxycholic acid", "Lactulose", "Prednisolone 40 mg daily", "Immediate liver transplant evaluation"]'::jsonb, 3, 'A Maddrey discriminant function above 32 indicates severe alcoholic hepatitis with high short-term mortality, and prednisolone 40 mg daily improves 28-day survival when infection, gastrointestinal bleeding, and renal failure have been excluded. N-acetylcysteine is used for acetaminophen toxicity and has no established role as monotherapy in alcoholic hepatitis. Ursodeoxycholic acid is used for cholestatic diseases such as primary biliary cholangitis. Lactulose treats hepatic encephalopathy, not alcoholic hepatitis. Transplant evaluation is premature during acute alcoholic hepatitis and requires sustained abstinence; corticosteroids are the immediate life-saving step.', 'Hard', 64, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 55-year-old man with a 25-year history of heavy alcohol use presents with jaundice, spider angiomata, palmar erythema, and gynecomastia. Labs show AST 180 U/L, ALT 70 U/L, total bilirubin 4.0 mg/dL, INR 1.8, and platelets 90,000 per microliter. What is the most likely diagnosis?', '["Acute viral hepatitis", "Metabolic dysfunction-associated steatotic liver disease", "Hemochromatosis", "Wilson disease", "Alcoholic cirrhosis"]'::jsonb, 4, 'Stigmata of chronic liver disease combined with an AST to ALT ratio greater than 2:1 and AST below 300 U/L is classic for alcohol-related liver disease, and thrombocytopenia reflects portal hypertension with hypersplenism. Acute viral hepatitis typically causes transaminases above 1000 U/L. Metabolic dysfunction-associated steatotic liver disease occurs with metabolic syndrome and usually shows ALT greater than AST. Hemochromatosis presents with diabetes, bronze skin, arthropathy, and elevated ferritin and transferrin saturation. Wilson disease presents in younger patients with neuropsychiatric features, Kayser-Fleischer rings, and low ceruloplasmin.', 'Medium', 65, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 46-year-old man with alcoholic hepatitis is improving with corticosteroid therapy and asks what will most improve his long-term survival. He currently drinks one pack of cigarettes daily and continues to drink alcohol. Which intervention is most important for his prognosis?', '["Sustained alcohol abstinence", "Daily prednisone indefinitely", "Ursodeoxycholic acid", "Vitamin E supplementation", "Pentoxifylline"]'::jsonb, 0, 'Sustained alcohol abstinence is the single most important intervention for survival at all stages of alcohol-related liver disease, slowing fibrosis progression and improving outcomes more than any drug; continued drinking negates other therapies. Long-term corticosteroids have no role after the acute episode and increase infection risk. Ursodeoxycholic acid is used for primary biliary cholangitis, not alcoholic liver disease. Vitamin E has been studied in nonalcoholic steatohepatitis, not alcohol-related disease. Pentoxifylline failed to show a survival benefit in the STOPAH trial and is not recommended.', 'Easy', 66, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 52-year-old woman with a body mass index of 34 kg/m2 and type 2 diabetes mellitus presents with mildly elevated liver enzymes: ALT 85 U/L and AST 60 U/L. She drinks minimal alcohol. Ultrasound shows hepatic steatosis, viral hepatitis serologies are negative, and transient elastography shows liver stiffness of 12 kPa. What is the most likely diagnosis and appropriate management?', '["Alcoholic liver disease; advise alcohol cessation", "Metabolic dysfunction-associated steatotic liver disease with advanced fibrosis; weight loss and diabetes control", "Autoimmune hepatitis; start prednisone", "Hemochromatosis; begin phlebotomy", "Primary biliary cholangitis; start ursodeoxycholic acid"]'::jsonb, 1, 'Metabolic risk factors with hepatic steatosis and a negative workup for other causes define metabolic dysfunction-associated steatotic liver disease, and a liver stiffness of 12 kPa suggests advanced fibrosis. Weight loss of 7 to 10 percent improves steatohepatitis and fibrosis, and control of diabetes and lipids is central to management. Her alcohol intake is minimal, making alcoholic liver disease unlikely. Autoimmune hepatitis would show positive autoantibodies and much higher transaminases. Hemochromatosis requires elevated iron indices. Ursodeoxycholic acid is used for primary biliary cholangitis and has no proven benefit in steatotic liver disease.', 'Medium', 67, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 58-year-old man with metabolic dysfunction-associated steatotic liver disease and F2 fibrosis has a body mass index of 38 kg/m2 and type 2 diabetes. He asks about medications that could help his liver disease. Which medication is most appropriate?', '["Prednisone", "Ursodeoxycholic acid", "A GLP-1 receptor agonist such as semaglutide", "Metronidazole", "Lactulose"]'::jsonb, 2, 'GLP-1 receptor agonists promote significant weight loss, improve glycemic control, and improve steatohepatitis, addressing the obesity and diabetes that drive metabolic dysfunction-associated steatotic liver disease; weight loss of 10 percent or more can even improve fibrosis. Vitamin E and pioglitazone are options in selected patients with biopsy-proven steatohepatitis, but a GLP-1 receptor agonist addresses obesity, diabetes, and cardiovascular risk together. Prednisone has no role and worsens metabolic disease and weight gain. Ursodeoxycholic acid has not shown benefit in steatotic liver disease. Metronidazole is an antibiotic with no role in this condition, and lactulose is used to treat hepatic encephalopathy, not steatotic liver disease.', 'Medium', 68, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 45-year-old man with metabolic dysfunction-associated steatotic liver disease has a FIB-4 score of 2.8. He is asymptomatic with normal bilirubin and albumin. What is the most appropriate next step?', '["Liver biopsy immediately", "Repeat FIB-4 in 5 years", "Start corticosteroids", "Transient elastography and hepatology referral", "CT scan of the abdomen"]'::jsonb, 3, 'A FIB-4 score above 2.67 indicates a high risk of advanced fibrosis and warrants confirmatory testing with vibration-controlled transient elastography and referral to hepatology, because advanced fibrosis triggers surveillance for hepatocellular carcinoma and varices. A low FIB-4 below 1.3 makes advanced fibrosis unlikely, while intermediate scores also need elastography. Liver biopsy is invasive and is reserved for cases where noninvasive testing is uncertain or another diagnosis is suspected. Repeating FIB-4 in 5 years would miss advanced disease that needs surveillance now. Corticosteroids have no role in steatotic liver disease, and CT scanning is poor for fibrosis staging and adds unnecessary radiation exposure.', 'Medium', 69, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 60-year-old man with cirrhosis has total bilirubin 2.5 mg/dL, albumin 3.0 g/dL, INR 1.8, moderate ascites, and no encephalopathy. What is his Child-Pugh score and class?', '["5, class A", "7, class B", "8, class B", "10, class C", "9, class B"]'::jsonb, 4, 'The Child-Pugh score assigns points as follows: bilirubin 2 to 3 mg/dL scores 2 points, albumin 2.8 to 3.5 g/dL scores 2 points, INR 1.7 to 2.3 scores 2 points, moderate ascites scores 2 points, and no encephalopathy scores 1 point, for a total of 9. Class B covers scores of 7 to 9, while class A is 5 to 6 and class C is 10 to 15. A score of 5 would require all parameters to be normal, which is not the case here. A score of 7 or 8 underestimates the points from bilirubin, INR, or ascites. A score of 10 would require worse encephalopathy or more severe ascites.', 'Hard', 70, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 58-year-old woman with cirrhosis is found to have a platelet count of 75,000 per microliter, splenomegaly on examination, and a normal white blood cell count and hemoglobin. Upper endoscopy shows no varices. What is the most likely cause of her thrombocytopenia?', '["Hypersplenism from portal hypertension", "Immune thrombocytopenic purpura", "Aplastic anemia", "Disseminated intravascular coagulation", "Heparin-induced thrombocytopenia"]'::jsonb, 0, 'Portal hypertension causes splenic enlargement with sequestration of platelets, producing mild to moderate thrombocytopenia in the range of 50,000 to 100,000 per microliter with preserved white blood cells and hemoglobin, which is the classic picture here. Immune thrombocytopenic purpura causes isolated and usually severe thrombocytopenia without splenomegaly. Aplastic anemia affects all three cell lines, not platelets alone. Disseminated intravascular coagulation presents with bleeding, prolonged clotting times, and schistocytes. Heparin-induced thrombocytopenia requires recent heparin exposure with a platelet fall of more than 50 percent.', 'Medium', 71, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 62-year-old man with cirrhosis presents with new-onset ascites. Diagnostic paracentesis shows serum albumin 3.0 g/dL, ascitic fluid albumin 1.2 g/dL, ascitic total protein 2.0 g/dL, and ascitic polymorphonuclear cell count 120 per mm3. The serum-ascites albumin gradient is 1.8 g/dL. What is the most likely cause of the ascites?', '["Peritoneal carcinomatosis", "Portal hypertension from cirrhosis", "Tuberculous peritonitis", "Nephrotic syndrome", "Pancreatitis"]'::jsonb, 1, 'A serum-ascites albumin gradient of 1.1 g/dL or higher indicates portal hypertension, and a gradient of 1.8 with low ascitic protein is characteristic of cirrhosis; the gradient is calculated from serum and ascitic albumin measured on the same day. Peritoneal carcinomatosis and tuberculous peritonitis produce a low gradient below 1.1 with high protein and lymphocyte predominance. Nephrotic syndrome causes low-gradient ascites from hypoalbuminemia without portal hypertension. Pancreatic ascites has a low gradient with markedly elevated amylase. The polymorphonuclear count of 120 per mm3 is below the 250 threshold for spontaneous bacterial peritonitis, so infection is not present here.', 'Medium', 72, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 57-year-old man with cirrhosis and ascites presents with fever and diffuse abdominal pain. Diagnostic paracentesis shows a polymorphonuclear cell count of 420 per mm3, and cultures are pending. He has no other source of infection. What is the most appropriate next step in management?', '["Diuretics alone", "Large-volume paracentesis only", "Cefotaxime plus albumin infusion", "Prednisone", "Observation without antibiotics"]'::jsonb, 2, 'An ascitic polymorphonuclear count of 250 per mm3 or higher diagnoses spontaneous bacterial peritonitis even before culture results return, and empiric third-generation cephalosporin therapy plus albumin reduces the risk of renal failure and death; albumin is typically given at 1.5 g/kg on day 1 and 1 g/kg on day 3. A repeat paracentesis at 48 hours should show a falling neutrophil count if treatment is working. Diuretics do not treat infection and should be held during acute infection. Large-volume paracentesis is diagnostic but not therapeutic for spontaneous bacterial peritonitis. Corticosteroids have no role in this infection, and observation risks progression to sepsis and hepatorenal syndrome.', 'Medium', 73, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 63-year-old man with cirrhosis recovered from an episode of spontaneous bacterial peritonitis 2 months ago. He now has ascitic fluid protein of 0.8 g/dL, total bilirubin 3.5 mg/dL, and creatinine 1.2 mg/dL. What is the most appropriate prophylaxis?', '["Weekly cefotaxime", "Lactulose", "Spironolactone", "Daily norfloxacin", "No prophylaxis"]'::jsonb, 3, 'A prior episode of spontaneous bacterial peritonitis is the strongest indication for lifelong secondary prophylaxis with daily norfloxacin 400 mg or trimethoprim-sulfamethoxazole, because the recurrence risk exceeds 70 percent without prophylaxis. Primary prophylaxis is also indicated when ascitic protein is below 1.5 g/dL with advanced liver disease, such as Child-Pugh score of 9 or higher, bilirubin of 3 mg/dL or higher, or creatinine of 1.2 mg/dL or higher. Intermittent cefotaxime is not used for prophylaxis. Lactulose prevents hepatic encephalopathy, not spontaneous bacterial peritonitis. Spironolactone manages ascites but does not prevent infection, and withholding prophylaxis after a documented episode is unacceptable given the high recurrence and mortality rates.', 'Medium', 74, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 54-year-old man with cirrhosis presents with hematemesis and melena. His heart rate is 115 beats per minute and blood pressure is 90/60 mmHg. Upper endoscopy shows actively bleeding esophageal varices. What is the most appropriate acute management?', '["Transjugular intrahepatic portosystemic shunt immediately", "High-dose proton pump inhibitor alone", "Sengstaken-Blakemore tube placement first", "Surgical portosystemic shunt", "Intravenous octreotide plus endoscopic band ligation"]'::jsonb, 4, 'A vasoactive drug such as octreotide combined with endoscopic variceal band ligation is first-line therapy for acute variceal bleeding, along with prophylactic antibiotics and restrictive transfusion targeting a hemoglobin of about 7 g/dL. Transjugular intrahepatic portosystemic shunt is rescue therapy for refractory bleeding, not first-line. A proton pump inhibitor alone is appropriate for ulcer bleeding, not variceal bleeding. Balloon tamponade is only a temporizing bridge when endoscopy is unavailable or fails. Surgical shunting is rarely used and carries high mortality in acutely ill cirrhotic patients.', 'Hard', 75, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 59-year-old woman with cirrhosis undergoes screening endoscopy that shows large esophageal varices. She has never had gastrointestinal bleeding and has no ascites. Her blood pressure is 110/70 mmHg and heart rate is 72 beats per minute. What is the most appropriate primary prophylaxis against variceal bleeding?', '["Nonselective beta-blocker such as nadolol or carvedilol", "Proton pump inhibitor", "Lactulose", "Diuretics", "Transjugular intrahepatic portosystemic shunt"]'::jsonb, 0, 'Large esophageal varices carry a high risk of bleeding and warrant primary prophylaxis with a nonselective beta-blocker or endoscopic band ligation; beta-blockers reduce portal pressure and are preferred when tolerated, and carvedilol is often favored in compensated cirrhosis. Endoscopic ligation is the alternative when beta-blockers are contraindicated or not tolerated. Proton pump inhibitors do not prevent variceal bleeding. Lactulose is used for hepatic encephalopathy, not variceal prophylaxis. Diuretics treat ascites but do not reduce variceal bleeding risk. Transjugular intrahepatic portosystemic shunt is not used for primary prophylaxis because of the risks of encephalopathy and shunt dysfunction.', 'Medium', 76, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 61-year-old man with cirrhosis has recurrent esophageal variceal bleeding despite treatment with a nonselective beta-blocker and two sessions of endoscopic band ligation. He is hemodynamically stable between episodes and has no hepatic encephalopathy. What is the most appropriate next step?', '["Repeat band ligation", "Transjugular intrahepatic portosystemic shunt", "Increase the beta-blocker dose", "Splenectomy", "Immediate liver transplant"]'::jsonb, 1, 'Transjugular intrahepatic portosystemic shunt is indicated for refractory variceal bleeding after failure of pharmacologic and endoscopic therapy because it directly decompresses portal pressure, and it also helps refractory ascites. Repeat band ligation has already failed twice and is unlikely to succeed. Increasing the beta-blocker dose is insufficient and is limited by hypotension and bradycardia. Splenectomy does not address portal hypertension. Liver transplant is definitive but is not immediately available, and a shunt serves as a bridge while the patient awaits transplant evaluation, provided there is no severe encephalopathy or prohibitively high bilirubin.', 'Hard', 77, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 66-year-old man with cirrhosis presents with new confusion and asterixis. He has had no bowel movement for 4 days and takes lactulose and furosemide. Labs show potassium 3.1 mEq/L and normal glucose. What is the most likely precipitant of his hepatic encephalopathy?', '["Hyperglycemia", "Hypothyroidism", "Constipation and hypokalemia", "Vitamin B12 deficiency", "Urinary retention"]'::jsonb, 2, 'Constipation increases colonic absorption of ammonia, and hypokalemia worsens encephalopathy by increasing renal ammonia production; diuretics cause both problems, making this combination the most likely precipitant. Other precipitants such as infection, gastrointestinal bleeding, sedatives, and dehydration should also be excluded, but the clinical picture here points to constipation and hypokalemia. Hyperglycemia does not precipitate hepatic encephalopathy. Hypothyroidism causes lethargy but not acute asterixis with this pattern. Vitamin B12 deficiency causes subacute combined degeneration of the spinal cord, not acute encephalopathy. Urinary retention can precipitate delirium but is less likely than the combined constipation and hypokalemia picture in this patient.', 'Medium', 78, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 64-year-old woman with cirrhosis has grade II hepatic encephalopathy. She takes lactulose 30 mL twice daily and has one bowel movement per day. She is alert but disoriented to time. What is the most appropriate adjustment to her therapy?', '["Stop lactulose", "Start rifaximin alone and stop lactulose", "Start prednisone", "Titrate lactulose to 2 to 3 soft stools daily", "Strict protein restriction"]'::jsonb, 3, 'Lactulose is first-line therapy for hepatic encephalopathy and should be titrated to produce 2 to 3 soft bowel movements daily; one stool per day is inadequate to clear colonic ammonia. Lactulose works by acidifying the colon, trapping ammonia as ammonium, and acting as a cathartic, but diarrhea and dehydration from over-titration must be avoided. Stopping lactulose would worsen encephalopathy. Rifaximin is add-on therapy for recurrent encephalopathy, not a substitute for lactulose. Prednisone has no role in hepatic encephalopathy. Protein restriction is harmful because it worsens sarcopenia in cirrhosis, and adequate protein intake is recommended in these patients.', 'Easy', 79, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 68-year-old man with cirrhosis has had three episodes of hepatic encephalopathy in the past 6 months despite taking lactulose titrated to 2 to 3 soft stools daily. He is currently alert and adherent to therapy. What is the most appropriate next step?', '["Stop lactulose", "Transjugular intrahepatic portosystemic shunt", "Liver transplant evaluation only", "Start metronidazole", "Add rifaximin to lactulose"]'::jsonb, 4, 'Rifaximin added to lactulose reduces the recurrence of hepatic encephalopathy by decreasing gut ammonia-producing bacteria and is the standard next step for breakthrough episodes despite adequate lactulose; it is minimally absorbed and is typically dosed at 550 mg twice daily. Lactulose should be continued alongside rifaximin rather than stopped. Stopping lactulose removes first-line therapy and would worsen encephalopathy. A transjugular intrahepatic portosystemic shunt can worsen encephalopathy by shunting ammonia past the liver. Transplant evaluation is appropriate but does not prevent the next episode. Metronidazole is not used for hepatic encephalopathy and carries a risk of neurotoxicity.', 'Medium', 80, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 34-year-old woman presents with fatigue, jaundice, and right upper quadrant discomfort. Labs show ALT 600 U/L, AST 450 U/L, elevated immunoglobulin G, positive antinuclear antibody and anti-smooth muscle antibody, and negative viral hepatitis serologies. Liver biopsy shows interface hepatitis with plasma cell infiltration. What is the most likely diagnosis and treatment?', '["Autoimmune hepatitis; prednisone with or without azathioprine", "Viral hepatitis; antiviral therapy", "Primary biliary cholangitis; ursodeoxycholic acid", "Hemochromatosis; therapeutic phlebotomy", "Wilson disease; penicillamine"]'::jsonb, 0, 'Autoimmune hepatitis classically presents in young women with markedly elevated transaminases, hypergammaglobulinemia, positive antinuclear and anti-smooth muscle antibodies, and interface hepatitis with plasma cells on biopsy; corticosteroids with or without azathioprine are first-line therapy, with azathioprine added as a steroid-sparing agent after checking thiopurine methyltransferase activity. It can also present as acute severe hepatitis, and overlap syndromes with cholestatic disease occur. Viral hepatitis is excluded by negative serologies. Primary biliary cholangitis is a cholestatic disease with positive antimitochondrial antibodies. Hemochromatosis presents with iron overload and diabetes, and Wilson disease presents with low ceruloplasmin and neuropsychiatric features.', 'Medium', 81, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 52-year-old woman presents with pruritus and fatigue. Labs show alkaline phosphatase 480 U/L, elevated gamma-glutamyl transferase, normal bilirubin, and positive antimitochondrial antibody. Antinuclear antibody is negative. What is the most likely diagnosis and treatment?', '["Primary sclerosing cholangitis; ursodeoxycholic acid", "Primary biliary cholangitis; ursodeoxycholic acid", "Autoimmune hepatitis; prednisone", "Gallstones; cholecystectomy", "Drug-induced cholestasis; stop the culprit drug"]'::jsonb, 1, 'Primary biliary cholangitis affects middle-aged women with chronic cholestasis and positive antimitochondrial antibody, and ursodeoxycholic acid is first-line therapy that improves transplant-free survival. Primary sclerosing cholangitis affects men with ulcerative colitis and shows beading on cholangiography, and ursodeoxycholic acid is not proven to improve survival there. Autoimmune hepatitis is a hepatocellular disease with antinuclear and anti-smooth muscle antibodies. Gallstones cause episodic biliary pain rather than chronic cholestasis with antimitochondrial antibody. Drug-induced cholestasis requires a culprit drug and lacks antimitochondrial antibody.', 'Medium', 82, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 38-year-old man with ulcerative colitis presents with pruritus and fatigue. Labs show alkaline phosphatase 520 U/L. Magnetic resonance cholangiopancreatography shows multifocal strictures and beading of the intrahepatic and extrahepatic bile ducts. What is the most likely diagnosis?', '["Primary biliary cholangitis", "Choledocholithiasis", "Primary sclerosing cholangitis", "Autoimmune hepatitis", "Pancreatic cancer"]'::jsonb, 2, 'Primary sclerosing cholangitis is strongly associated with ulcerative colitis and shows characteristic multifocal strictures with beading on cholangiography; these patients need surveillance for cholangiocarcinoma, including evaluation of any dominant stricture with brush cytology, as well as annual colon cancer surveillance because of the markedly increased colorectal cancer risk. Primary biliary cholangitis affects women with positive antimitochondrial antibody and a normal cholangiogram. Choledocholithiasis causes acute biliary obstruction, not multifocal strictures. Autoimmune hepatitis is a hepatocellular disease with markedly elevated transaminases. Pancreatic cancer causes a single distal bile duct stricture with weight loss.', 'Medium', 83, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 48-year-old man presents with fatigue, arthralgia of the metacarpophalangeal joints, diabetes mellitus, and bronze-colored skin. Labs show ferritin 1200 ng/mL and transferrin saturation 78 percent. What is the most likely diagnosis and treatment?', '["Wilson disease; penicillamine", "Alcoholic liver disease; alcohol cessation", "Metabolic dysfunction-associated steatotic liver disease; weight loss", "Hereditary hemochromatosis; therapeutic phlebotomy", "Porphyria cutanea tarda; phlebotomy and sun avoidance"]'::jsonb, 3, 'Hereditary hemochromatosis causes iron overload with the classic triad of diabetes, arthropathy, and skin pigmentation; a transferrin saturation above 45 percent with ferritin above 1000 ng/mL is diagnostic, and therapeutic phlebotomy is first-line treatment. Wilson disease presents in younger patients with low ceruloplasmin and Kayser-Fleischer rings. Alcoholic liver disease lacks iron overload and metacarpophalangeal arthropathy. Steatotic liver disease can raise ferritin mildly but does not raise transferrin saturation to 78 percent. Porphyria cutanea tarda causes blistering skin lesions, not this systemic picture.', 'Medium', 84, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 22-year-old man presents with tremor, dysarthria, and psychiatric changes over 6 months. Examination shows Kayser-Fleischer rings on slit-lamp examination. Labs show low ceruloplasmin and elevated 24-hour urinary copper excretion. What is the most likely diagnosis?', '["Hemochromatosis", "Parkinson disease", "Huntington disease", "Multiple sclerosis", "Wilson disease"]'::jsonb, 4, 'Wilson disease is caused by ATP7B-related copper accumulation and presents in young adults with movement disorder, psychiatric symptoms, Kayser-Fleischer rings, low ceruloplasmin, and elevated urinary copper; it is autosomal recessive, so first-degree relatives should be screened, and hepatic copper quantification can confirm the diagnosis when uncertain. Hemochromatosis affects older adults with diabetes, arthropathy, and iron overload. Parkinson disease lacks Kayser-Fleischer rings and hepatic features. Huntington disease is autosomal dominant with chorea and a family history. Multiple sclerosis causes demyelinating relapses and does not cause copper abnormalities or Kayser-Fleischer rings.', 'Medium', 85, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 19-year-old woman is newly diagnosed with Wilson disease with hepatic involvement and elevated transaminases. She has no neurologic symptoms. What is the most appropriate initial treatment?', '["Penicillamine or trientine chelation therapy", "Therapeutic phlebotomy", "Ursodeoxycholic acid", "Prednisone", "Lactulose"]'::jsonb, 0, 'Chelation therapy with penicillamine or trientine removes excess copper and is first-line treatment for symptomatic Wilson disease; zinc is used for maintenance therapy and for presymptomatic patients. Penicillamine can cause proteinuria and bone marrow suppression, while trientine is generally better tolerated, and therapy is lifelong with avoidance of copper-rich foods. Therapeutic phlebotomy treats iron overload in hemochromatosis, not copper overload. Ursodeoxycholic acid is used for cholestatic diseases such as primary biliary cholangitis. Prednisone treats autoimmune hepatitis. Lactulose treats hepatic encephalopathy and has no role in Wilson disease.', 'Easy', 86, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 28-year-old woman ingested 15 grams of acetaminophen 6 hours ago in a suicide attempt. She is currently asymptomatic with normal AST and ALT. Her serum acetaminophen level is above the treatment line on the Rumack-Matthew nomogram. What is the most appropriate management?', '["Activated charcoal only", "N-acetylcysteine infusion", "Observation without treatment", "Lactulose", "Liver transplant evaluation"]'::jsonb, 1, 'N-acetylcysteine replenishes glutathione and prevents hepatotoxicity when started early in acetaminophen overdose above the nomogram treatment line, and it remains effective even after liver injury develops; it is most effective within 8 hours but should be given regardless of timing when indicated, using the standard 21-hour intravenous protocol. Activated charcoal is only useful within 1 hour of ingestion. Observation risks progression to fulminant hepatic failure because liver injury develops over 24 to 72 hours. Lactulose treats hepatic encephalopathy, not acute acetaminophen toxicity. Liver transplant is reserved for established acute liver failure meeting transplant criteria, which this patient does not yet have.', 'Medium', 87, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 32-year-old man with acetaminophen-induced acute liver failure has INR 4.5, grade III hepatic encephalopathy, total bilirubin 18 mg/dL, arterial pH 7.28, and creatinine 2.4 mg/dL. He is in the intensive care unit receiving N-acetylcysteine. What is the most appropriate next step?', '["Lactulose alone", "High-dose corticosteroids", "Urgent liver transplant evaluation and intensive care", "Transjugular intrahepatic portosystemic shunt", "Discharge home with close follow-up"]'::jsonb, 2, 'Acetaminophen-induced acute liver failure with grade III encephalopathy, severe coagulopathy, metabolic acidosis, and renal failure meets King''s College criteria for poor prognosis without transplant, so urgent transplant evaluation and intensive care are indicated. The criteria include arterial pH below 7.30 after resuscitation, or INR above 6.5 with creatinine above 3.4 mg/dL and grade III or IV encephalopathy. Lactulose alone is inadequate for fulminant liver failure. Corticosteroids have no role in acetaminophen-induced acute liver failure. A transjugular intrahepatic portosystemic shunt treats portal hypertension, not liver failure. Discharge is unsafe in fulminant hepatic failure with multisystem involvement.', 'Hard', 88, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 60-year-old man with hepatitis C cirrhosis that is well compensated asks about screening for liver cancer. He has no symptoms and normal liver function tests. What is the most appropriate screening recommendation?', '["CT scan every year", "Alpha-fetoprotein alone every 6 months", "No screening is needed", "Ultrasound every 6 months with or without alpha-fetoprotein", "Liver biopsy every year"]'::jsonb, 3, 'Guidelines recommend ultrasound every 6 months with or without alpha-fetoprotein for hepatocellular carcinoma surveillance in patients with cirrhosis, because it is cost-effective and detects early tumors that are amenable to curative treatment; some guidelines add alpha-fetoprotein to improve sensitivity. Surveillance is also recommended for chronic hepatitis B patients at high risk even without cirrhosis. Annual CT scanning adds radiation exposure and cost without proven benefit over ultrasound. Alpha-fetoprotein alone lacks sensitivity and specificity for screening. Screening is indicated because cirrhosis carries a high risk of hepatocellular carcinoma. Liver biopsy is a diagnostic procedure, not a screening tool.', 'Easy', 89, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 64-year-old man with hepatitis B cirrhosis undergoes surveillance ultrasound that shows a 3 cm liver mass. Alpha-fetoprotein is 850 ng/mL. Contrast-enhanced CT shows arterial phase hyperenhancement with portal venous washout. What is the most likely diagnosis?', '["Hepatic adenoma", "Focal nodular hyperplasia", "Hemangioma", "Metastatic colon cancer", "Hepatocellular carcinoma"]'::jsonb, 4, 'In a cirrhotic patient, a liver mass with arterial phase hyperenhancement and portal venous washout plus markedly elevated alpha-fetoprotein is diagnostic of hepatocellular carcinoma by LI-RADS criteria without the need for biopsy; a LI-RADS 5 lesion is considered definitively hepatocellular carcinoma. Biopsy is avoided because of bleeding risk and the small risk of tumor seeding. Hepatic adenoma occurs in young women taking oral contraceptives without cirrhosis. Focal nodular hyperplasia has a central scar and normal alpha-fetoprotein. Hemangioma shows peripheral nodular enhancement. Metastatic colon cancer lacks the washout pattern and usually has a known primary tumor with normal alpha-fetoprotein.', 'Medium', 90, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 52-year-old woman with a history of gallstones presents to the emergency department with 12 hours of severe epigastric pain radiating to her back, nausea, and vomiting. She is afebrile, heart rate is 112/min, and blood pressure is 118/74 mmHg. Examination shows epigastric tenderness without guarding. Laboratory studies show lipase 1,840 U/L (normal <160), amylase 980 U/L, white blood cell count 13,200/mm3, and normal liver enzymes. Abdominal ultrasound shows gallstones and a normal common bile duct. What is the most appropriate initial management?', '["Immediate endoscopic retrograde cholangiopancreatography", "Aggressive intravenous isotonic fluid resuscitation with lactated Ringer solution", "Intravenous antibiotics and urgent surgical consultation for necrosectomy", "Oral pancreatic enzyme replacement therapy", "Nasogastric tube placement and total parenteral nutrition"]'::jsonb, 1, 'Gallstone pancreatitis is diagnosed by characteristic epigastric pain radiating to the back with lipase more than three times the upper limit of normal. The cornerstone of initial management is aggressive early isotonic intravenous fluid resuscitation, preferably lactated Ringer solution, to maintain pancreatic perfusion and prevent organ failure. ERCP is indicated only when there is concurrent cholangitis or persistent biliary obstruction, not for uncomplicated gallstone pancreatitis. Antibiotics are not given prophylactically and necrosectomy is reserved for infected necrosis. Pancreatic enzyme replacement treats exocrine insufficiency, not acute pancreatitis. Early enteral nutrition is preferred over total parenteral nutrition once the patient can tolerate it.', 'Medium', 91, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 48-year-old man with chronic alcohol use presents with severe epigastric pain, vomiting, and fever for 3 days. He is tachycardic and hypotensive. Laboratory studies show lipase 2,400 U/L, calcium 7.1 mg/dL, blood urea nitrogen 34 mg/dL, and hematocrit 52%. Contrast-enhanced CT of the abdomen performed 72 hours after symptom onset shows pancreatic necrosis involving 40% of the gland without a discrete fluid collection. Blood cultures are negative and he is on broad-spectrum antibiotics. On hospital day 10 he develops worsening fever, leukocytosis, and gas within the necrotic collection on repeat CT. What is the most appropriate next step in management?', '["Continue antibiotics alone and repeat imaging in 1 week", "Immediate open surgical necrosectomy", "Step-up approach with percutaneous catheter drainage followed by minimally invasive necrosectomy if needed", "Start total parenteral nutrition and keep the patient nil per os", "Endoscopic retrograde cholangiopancreatography with pancreatic duct stenting"]'::jsonb, 2, 'This patient has infected pancreatic necrosis, suggested by fever, leukocytosis, and gas in the necrotic collection after the first week of illness. The step-up approach, beginning with percutaneous or endoscopic catheter drainage and escalating to minimally invasive necrosectomy only if drainage fails, reduces mortality and complications compared with immediate open necrosectomy. Antibiotics alone are insufficient for infected necrosis with gas. Prolonged nil per os status and total parenteral nutrition worsen outcomes; enteral nutrition is preferred. ERCP is indicated for biliary obstruction or cholangitis, not for infected necrosis. Early CT within 48 hours underestimates necrosis, which is why imaging was appropriately delayed to 72 hours.', 'Hard', 92, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 45-year-old man is seen in clinic 8 weeks after an episode of severe acute pancreatitis that required hospitalization. He reports persistent early satiety, vague epigastric fullness, and a 5-kg weight loss since discharge. He is afebrile with normal vital signs. Abdominal examination shows mild epigastric tenderness without a palpable mass. CT of the abdomen shows a 7-cm well-defined fluid collection adjacent to the pancreas with a thick enhancing wall and no solid debris. Serum amylase is mildly elevated. What is the most appropriate management?', '["Observation alone because most collections resolve spontaneously", "Open surgical cystojejunostomy", "Intravenous antibiotics for 4 weeks", "Endoscopic ultrasound-guided cystogastrostomy with stent placement", "Percutaneous aspiration of the collection for culture"]'::jsonb, 3, 'A mature, well-encapsulated fluid collection appearing more than 4 weeks after acute pancreatitis with a thick wall and no solid debris is a pancreatic pseudocyst. Symptomatic pseudocysts causing early satiety, pain, or weight loss require drainage, and endoscopic ultrasound-guided cystogastrostomy with stent placement is the preferred minimally invasive approach. Observation is appropriate only for small asymptomatic pseudocysts, many of which resolve, but this 7-cm collection is symptomatic. Open surgery is reserved for failed endoscopic drainage. Antibiotics are not indicated without infection, and percutaneous aspiration is discouraged because it risks infection and recurrence without definitive drainage.', 'Hard', 93, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 58-year-old man with a 25-year history of heavy alcohol use presents with 6 months of recurrent epigastric pain, bulky foul-smelling stools, and a 9-kg weight loss. He reports new-onset diabetes diagnosed 3 months ago. Examination shows epigastric tenderness and temporal wasting. Laboratory studies show fasting glucose 212 mg/dL and normal liver enzymes. CT of the abdomen shows pancreatic calcifications, a dilated pancreatic duct, and pancreatic atrophy. What is the most likely diagnosis?', '["Chronic pancreatitis", "Pancreatic adenocarcinoma", "Autoimmune pancreatitis", "Celiac disease", "Gastroparesis from diabetes"]'::jsonb, 0, 'Chronic pancreatitis from long-standing alcohol use causes recurrent epigastric pain, exocrine insufficiency with steatorrhea and weight loss, and endocrine insufficiency with diabetes (type 3c diabetes). Pancreatic calcifications, a dilated duct, and atrophy on CT are classic findings. Pancreatic adenocarcinoma typically presents with painless jaundice and a pancreatic mass rather than diffuse calcifications. Autoimmune pancreatitis shows a sausage-shaped pancreas with a capsule-like rim and responds to steroids. Celiac disease causes malabsorption but not pancreatic calcifications or chronic epigastric pain. Diabetic gastroparesis causes nausea and early satiety, not steatorrhea or pancreatic calcifications.', 'Medium', 94, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 62-year-old man with chronic pancreatitis from alcohol use reports persistent bulky, greasy stools that float and are difficult to flush, along with progressive weight loss despite a good appetite. He has no jaundice or abdominal mass. Laboratory studies show low serum vitamin D and vitamin A levels. Fecal elastase is 68 mcg/g (normal >200). What is the most appropriate treatment?', '["High-dose proton pump inhibitor alone", "Low-fat diet alone without enzyme supplementation", "Octreotide injections", "Surgical pancreaticoduodenectomy", "Pancreatic enzyme replacement therapy with meals"]'::jsonb, 4, 'A low fecal elastase below 100 mcg/g confirms pancreatic exocrine insufficiency, which in chronic pancreatitis causes steatorrhea, weight loss, and fat-soluble vitamin deficiency. Pancreatic enzyme replacement therapy taken with meals restores fat digestion and improves nutrition. A proton pump inhibitor alone does not replace missing enzymes, though it may be added to improve enzyme efficacy by reducing gastric acid inactivation. A low-fat diet alone is insufficient and worsens malnutrition. Octreotide is used for variceal bleeding and neuroendocrine tumors, not exocrine insufficiency. Pancreaticoduodenectomy is reserved for malignancy or refractory pain, not for uncomplicated exocrine insufficiency.', 'Medium', 95, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 55-year-old man with chronic pancreatitis has daily severe epigastric pain despite abstinence from alcohol, pancreatic enzyme replacement, and maximal doses of acetaminophen and tramadol. He has lost 12 kg over the past year. CT shows a dilated pancreatic duct with an obstructing stone in the head of the pancreas and no mass. Endoscopic retrograde cholangiopancreatography with stone extraction was unsuccessful. What is the most appropriate next step in management?', '["Start high-dose morphine and continue indefinitely", "Total pancreatectomy with islet autotransplantation as first-line therapy", "Celiac plexus neurolysis with alcohol injection", "Referral for surgical pancreatic duct drainage procedure such as a longitudinal pancreaticojejunostomy", "Repeat endoscopic retrograde cholangiopancreatography every month"]'::jsonb, 3, 'Refractory pain in chronic pancreatitis with a dilated pancreatic duct and an obstructing stone is best treated by surgical ductal drainage, such as a longitudinal pancreaticojejunostomy (Puestow procedure), which decompresses the duct and relieves pain. Escalating opioids worsens dependence and does not address the underlying obstruction. Total pancreatectomy with islet autotransplantation is reserved for small-duct disease refractory to all other measures and carries major morbidity. Celiac plexus block provides only temporary relief and is not first-line when a correctable ductal obstruction exists. Repeated unsuccessful endoscopy delays definitive therapy and adds procedural risk.', 'Hard', 96, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 68-year-old man presents with 2 months of painless jaundice, pruritus, dark urine, clay-colored stools, and a 10-kg weight loss. He reports new-onset diabetes diagnosed 4 months ago and intermittent dull epigastric pain radiating to his back. Examination shows jaundice, a palpable nontender gallbladder, and no hepatomegaly. Laboratory studies show total bilirubin 9.2 mg/dL with direct bilirubin 7.4 mg/dL, alkaline phosphatase 480 U/L, and CA 19-9 of 850 U/mL. CT of the abdomen shows a 3.5-cm mass in the head of the pancreas encasing the superior mesenteric artery. What is the most likely diagnosis?', '["Choledocholithiasis with secondary cholangitis", "Gallbladder carcinoma", "Pancreatic adenocarcinoma of the head of the pancreas", "Autoimmune pancreatitis", "Cholangiocarcinoma of the distal common bile duct"]'::jsonb, 2, 'Painless jaundice with a palpable nontender gallbladder is Courvoisier sign, classic for malignant obstruction of the distal common bile duct, most often pancreatic head adenocarcinoma. New-onset diabetes, weight loss, and back pain further support pancreatic cancer, and a pancreatic head mass encasing the superior mesenteric artery confirms it and renders it locally unresectable. Choledocholithiasis causes episodic pain and fluctuating jaundice rather than a mass. Gallbladder carcinoma typically presents with a gallbladder mass and right upper quadrant pain. Autoimmune pancreatitis causes a diffusely enlarged pancreas that responds to steroids. Distal cholangiocarcinoma can mimic pancreatic cancer but the pancreatic mass points to adenocarcinoma.', 'Medium', 97, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 60-year-old woman with a 30 pack-year smoking history and a family history of pancreatic cancer in her father and brother presents for counseling. She has no symptoms, normal examination, and normal laboratory studies. She asks about her risk of pancreatic cancer and whether screening is recommended. Which of the following is the most accurate statement?', '["Smoking is not a risk factor for pancreatic cancer", "Screening with annual CA 19-9 alone is recommended for all first-degree relatives of patients with pancreatic cancer", "She is at increased risk because of smoking and family history, and screening with endoscopic ultrasound or MRI is considered only for high-risk individuals in specialized programs", "Chronic pancreatitis protects against pancreatic cancer", "New-onset diabetes after age 50 has no association with pancreatic cancer"]'::jsonb, 3, 'Smoking is the strongest modifiable risk factor for pancreatic cancer, and having two first-degree relatives with the disease substantially increases risk, possibly reflecting a hereditary syndrome such as BRCA2. Screening is not recommended for the general population or for all relatives; surveillance with endoscopic ultrasound or MRI is offered only to high-risk individuals in specialized programs. CA 19-9 alone is not a screening test because it lacks sensitivity and specificity. Chronic pancreatitis increases, rather than protects against, pancreatic cancer risk. New-onset diabetes after age 50 is a recognized early manifestation of pancreatic cancer and warrants evaluation.', 'Medium', 98, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 72-year-old man with a pancreatic head adenocarcinoma metastatic to the liver presents with progressive jaundice, pruritus, and dark urine. His bilirubin is 11.4 mg/dL. He is not a surgical candidate and has an expected survival of several months. He is about to start systemic chemotherapy. What is the most appropriate next step to relieve his biliary obstruction?', '["Endoscopic placement of a self-expanding metal biliary stent", "Surgical biliary bypass with hepaticojejunostomy", "Percutaneous transhepatic biliary drainage as first-line therapy", "Observation because chemotherapy will shrink the tumor and relieve obstruction", "External beam radiation to the pancreatic head"]'::jsonb, 0, 'In unresectable pancreatic cancer with malignant biliary obstruction, endoscopic placement of a self-expanding metal stent is the preferred palliative approach because it relieves jaundice and pruritus with lower morbidity than surgery, and metal stents remain patent longer than plastic stents in patients expected to live more than a few months. Surgical biliary bypass is reserved for patients found unresectable at laparotomy or with gastric outlet obstruction. Percutaneous drainage is second-line when endoscopic stenting fails or is not technically possible. Chemotherapy alone cannot be relied upon to relieve obstruction promptly. Radiation does not reliably or rapidly decompress the bile duct.', 'Medium', 99, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 44-year-old obese woman presents with recurrent episodes of right upper quadrant pain lasting 30 to 60 minutes, occurring after fatty meals and resolving spontaneously. She has no fever, jaundice, or vomiting. Examination is normal between episodes. Laboratory studies including liver enzymes and bilirubin are normal. Ultrasound shows multiple gallstones in the gallbladder with a normal gallbladder wall and a normal common bile duct. What is the most appropriate management?', '["Reassurance and observation without surgery", "Ursodeoxycholic acid dissolution therapy", "Endoscopic retrograde cholangiopancreatography", "Low-fat diet and antispasmodic medication indefinitely", "Laparoscopic cholecystectomy"]'::jsonb, 4, 'Recurrent biliary colic from symptomatic gallstones is an indication for laparoscopic cholecystectomy, which prevents progression to cholecystitis, choledocholithiasis, and pancreatitis. Observation is appropriate only for asymptomatic gallstones, which have a low annual rate of complications. Ursodeoxycholic acid dissolves only small cholesterol stones, works slowly, and has high recurrence rates after stopping. ERCP is used for common bile duct stones, not for gallbladder stones with a normal bile duct. Dietary modification and antispasmodics do not prevent recurrent colic or complications in symptomatic gallstone disease.', 'Easy', 100, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 58-year-old woman undergoes abdominal ultrasound for evaluation of vague abdominal discomfort. The ultrasound shows multiple gallstones in the gallbladder with a thin gallbladder wall and a normal common bile duct. She has no history of biliary colic, fever, or jaundice, and her examination and liver enzymes are normal. The discomfort has resolved and is thought to be musculoskeletal. What is the most appropriate management of her gallstones?', '["No treatment is needed for asymptomatic gallstones", "Prophylactic laparoscopic cholecystectomy", "Ursodeoxycholic acid dissolution therapy", "Endoscopic retrograde cholangiopancreatography to remove the stones", "Low-fat diet and prophylactic antibiotics"]'::jsonb, 0, 'Asymptomatic gallstones found incidentally do not require treatment, because the annual risk of developing symptoms or complications is only about 1 to 2 percent, and prophylactic cholecystectomy carries surgical risk without benefit. Treatment is reserved for symptomatic gallstones, such as biliary colic, cholecystitis, or choledocholithiasis. Ursodeoxycholic acid is not indicated for asymptomatic stones. ERCP is used for common bile duct stones, not for asymptomatic gallbladder stones. Dietary changes do not dissolve existing stones or prevent complications, and prophylactic antibiotics have no role in the absence of infection.', 'Medium', 101, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 76-year-old woman with a history of gallstones presents with 3 days of abdominal distension, bilious vomiting, and inability to pass stool or flatus. She has no fever. Examination shows a distended abdomen with hyperactive bowel sounds and mild diffuse tenderness. Abdominal radiograph shows dilated loops of small bowel with air-fluid levels and gas in the biliary tree. CT of the abdomen shows a 3-cm calcified stone impacted at the ileocecal valve and pneumobilia. What is the most likely diagnosis?', '["Common bile duct stone causing biliary obstruction", "Gallstone ileus from a cholecystoenteric fistula with stone impaction at the ileocecal valve", "Acute cholecystitis with gallbladder perforation", "Necrotizing pancreatitis from gallstone migration", "Bouveret syndrome with gastric outlet obstruction"]'::jsonb, 1, 'Gallstone ileus occurs when a large gallstone erodes through the gallbladder wall into the duodenum through a cholecystoenteric fistula and then impacts at the ileocecal valve, causing small bowel obstruction. The classic radiographic finding is pneumobilia, or gas in the biliary tree, from the fistula, together with small bowel obstruction. A stone in the common bile duct causes jaundice and cholangitis rather than bowel obstruction. Acute cholecystitis presents with right upper quadrant pain, fever, and a thickened gallbladder wall. Pancreatic necrosis causes severe epigastric pain and systemic inflammation. Bouveret syndrome is the related gastric outlet obstruction when the stone impacts in the duodenum, not at the ileocecal valve.', 'Hard', 102, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 47-year-old woman presents with 24 hours of right upper quadrant pain, nausea, and fever to 38.6°C. Examination shows right upper quadrant tenderness with a positive Murphy sign. Laboratory studies show white blood cell count 15,800/mm3, normal bilirubin, and mildly elevated alkaline phosphatase. Ultrasound shows a gallstone impacted in the gallbladder neck, gallbladder wall thickening of 5 mm, pericholecystic fluid, and a positive sonographic Murphy sign. What is the most appropriate management?', '["Intravenous antibiotics alone for 2 weeks", "Observation with a low-fat diet and repeat imaging in 1 month", "Early laparoscopic cholecystectomy within 72 hours of symptom onset", "Ursodeoxycholic acid dissolution therapy", "Percutaneous cholecystostomy as first-line therapy"]'::jsonb, 2, 'Acute calculous cholecystitis is diagnosed by right upper quadrant pain, fever, leukocytosis, and imaging showing gallbladder wall thickening, pericholecystic fluid, and a sonographic Murphy sign. Early laparoscopic cholecystectomy within 72 hours of symptom onset is the preferred treatment because it reduces hospital stay, complications, and recurrence compared with delayed surgery. Antibiotics alone are insufficient because the obstructed gallbladder requires source control. Ursodeoxycholic acid works slowly and is not useful in acute inflammation. Percutaneous cholecystostomy is reserved for patients who are too high risk for surgery. Observation risks progression to gangrene or perforation.', 'Medium', 103, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 74-year-old man with type 2 diabetes presents with 3 days of right upper quadrant pain, fever to 39.1°C, and confusion. Examination shows right upper quadrant tenderness with guarding. Laboratory studies show white blood cell count 21,000/mm3, glucose 320 mg/dL, and bilirubin 1.1 mg/dL. Ultrasound shows gallstones, a thickened gallbladder wall, pericholecystic fluid, and gas within the gallbladder wall. What is the most appropriate management?', '["Discharge home on oral antibiotics with close follow-up", "Intravenous antibiotics alone for 7 days without surgery", "HIDA scan to confirm the diagnosis before any intervention", "Urgent laparoscopic or open cholecystectomy", "Percutaneous cholecystostomy as definitive treatment"]'::jsonb, 3, 'Elderly diabetic patients are at high risk for gangrenous cholecystitis, which can progress rapidly to perforation with few warning signs because autonomic neuropathy blunts pain. Urgent cholecystectomy is the definitive treatment and should not be delayed. Antibiotics alone are inadequate when the gallbladder is gangrenous and at risk of perforation. Percutaneous cholecystostomy is an alternative only when the patient is a prohibitive surgical risk, which is not established here. HIDA scan would delay definitive care in a patient with clear imaging of cholecystitis and signs of gangrene. Discharge on oral antibiotics is unsafe and risks perforation and sepsis.', 'Hard', 104, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 39-year-old woman presents with 36 hours of right upper quadrant pain, nausea, and low-grade fever. Examination shows right upper quadrant tenderness but no clear Murphy sign. Laboratory studies show white blood cell count 12,400/mm3 and normal liver enzymes. Ultrasound shows gallstones and a borderline gallbladder wall thickness of 3 mm without pericholecystic fluid or a sonographic Murphy sign. The diagnosis remains uncertain. What is the most appropriate next diagnostic test?', '["Repeat abdominal ultrasound in 24 hours", "CT of the abdomen with contrast", "Magnetic resonance cholangiopancreatography", "Endoscopic retrograde cholangiopancreatography", "HIDA scan"]'::jsonb, 4, 'When ultrasound is equivocal in suspected acute cholecystitis, a HIDA scan is the most sensitive test; nonvisualization of the gallbladder after 4 hours indicates cystic duct obstruction and confirms cholecystitis. CT is less sensitive for acute cholecystitis and is more useful for complications such as perforation or emphysematous cholecystitis. MRCP visualizes the biliary tree but is not the test of choice for acute cholecystitis. ERCP is therapeutic for common bile duct stones and carries procedural risk, so it is not a diagnostic test for cholecystitis. A normal white blood cell count does not exclude cholecystitis, and repeating ultrasound is less useful than proceeding to HIDA imaging.', 'Medium', 105, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 61-year-old woman presents with 2 days of right upper quadrant pain, jaundice, and dark urine. She is afebrile with normal vital signs. Laboratory studies show total bilirubin 4.8 mg/dL with direct bilirubin 3.9 mg/dL, alkaline phosphatase 420 U/L, alanine aminotransferase 110 U/L, and normal lipase. Ultrasound shows gallstones and a common bile duct dilated to 11 mm with a 9-mm echogenic stone in the distal duct. What is the most appropriate next step in management?', '["Magnetic resonance cholangiopancreatography", "Endoscopic retrograde cholangiopancreatography immediately", "HIDA scan", "Endoscopic ultrasound as the only available option", "Observation with repeat liver enzymes in 1 week"]'::jsonb, 0, 'Choledocholithiasis is suggested by a cholestatic pattern with markedly elevated alkaline phosphatase and bilirubin, a dilated common bile duct, and a stone visualized on imaging. Magnetic resonance cholangiopancreatography is the preferred noninvasive confirmatory test for suspected common bile duct stones when the patient is stable and there is no cholangitis. ERCP is therapeutic and is reserved for patients with cholangitis, persistent obstruction, or a high probability of stones requiring intervention, because it carries risks of pancreatitis and bleeding. HIDA scan evaluates the gallbladder, not the bile duct. Endoscopic ultrasound is an alternative but MRCP is the standard first test. Observation is unsafe because an impacted stone can progress to cholangitis or pancreatitis.', 'Medium', 106, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 66-year-old woman presents with 12 hours of fever to 39.4°C, shaking chills, right upper quadrant pain, and jaundice. She is hypotensive with blood pressure 88/54 mmHg and confused. Laboratory studies show white blood cell count 19,500/mm3, total bilirubin 6.2 mg/dL, and alkaline phosphatase 510 U/L. Ultrasound shows gallstones and a dilated common bile duct. Blood cultures are drawn. What is the most appropriate management?', '["Intravenous antibiotics alone for 7 days", "Broad-spectrum antibiotics with urgent endoscopic retrograde cholangiopancreatography and stone extraction", "Laparoscopic cholecystectomy alone", "Percutaneous transhepatic biliary drainage as first-line therapy", "Ursodeoxycholic acid to dissolve the stone"]'::jsonb, 1, 'Acute cholangitis presents with Charcot triad of fever, right upper quadrant pain, and jaundice, and hypotension with altered mental status completes Reynolds pentad. The treatment is broad-spectrum antibiotics plus prompt biliary decompression, with endoscopic retrograde cholangiopancreatography with sphincterotomy and stone extraction being the preferred approach. Antibiotics alone cannot decompress an obstructed, infected biliary tree and mortality is high without drainage. Cholecystectomy alone does not relieve common bile duct obstruction. Percutaneous drainage is second-line when endoscopy is not feasible. Ursodeoxycholic acid dissolves cholesterol stones slowly and has no role in acute cholangitis.', 'Medium', 107, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 34-year-old man with a 6-year history of ulcerative colitis presents with 4 months of progressive fatigue, pruritus, and intermittent jaundice. Laboratory studies show alkaline phosphatase 620 U/L, gamma-glutamyl transferase 480 U/L, total bilirubin 3.1 mg/dL, and normal transaminases. Magnetic resonance cholangiopancreatography shows multifocal strictures and dilations of the intrahepatic and extrahepatic bile ducts with a beaded appearance. What is the most likely diagnosis?', '["Primary biliary cholangitis", "Autoimmune hepatitis", "Primary sclerosing cholangitis", "Choledocholithiasis", "Caroli disease"]'::jsonb, 2, 'Primary sclerosing cholangitis is a chronic cholestatic liver disease characterized by multifocal strictures and dilations of the bile ducts, giving a beaded appearance on cholangiography, and it is strongly associated with ulcerative colitis. It carries a markedly increased risk of cholangiocarcinoma. Primary biliary cholangitis affects the small intrahepatic ducts and is associated with antimitochondrial antibodies and middle-aged women, not ulcerative colitis. Autoimmune hepatitis causes a hepatocellular pattern with elevated transaminases and autoantibodies. Choledocholithiasis causes intermittent obstruction rather than progressive beaded strictures. Caroli disease causes congenital segmental dilation of intrahepatic ducts without the ulcerative colitis association.', 'Hard', 108, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 68-year-old man in the intensive care unit after major abdominal surgery for a perforated viscus develops fever to 39.0°C, leukocytosis, and mild right upper quadrant tenderness on hospital day 8. He has been nil per os and on total parenteral nutrition. Ultrasound shows a distended gallbladder with a thickened wall and sludge but no gallstones, and a normal common bile duct. Blood cultures are negative. He remains hypotensive on vasopressors and is a poor surgical candidate. What is the most appropriate management?', '["Emergency open cholecystectomy", "Intravenous antibiotics alone", "HIDA scan to confirm the diagnosis", "Percutaneous cholecystostomy", "Ursodeoxycholic acid therapy"]'::jsonb, 3, 'Acalculous cholecystitis occurs most often in critically ill patients, such as those in the intensive care unit with sepsis, trauma, burns, or prolonged fasting, because gallbladder stasis and ischemia lead to inflammation without stones. It often presents subtly with fever and leukocytosis rather than classic right upper quadrant pain. Percutaneous cholecystostomy is the preferred treatment in critically ill patients who are poor surgical candidates because it decompresses the gallbladder with less risk than surgery. Emergency cholecystectomy is high risk in this setting. Antibiotics alone are inadequate without drainage. Ursodeoxycholic acid is for cholesterol stones, which are absent here. ERCP does not treat gallbladder inflammation.', 'Medium', 109, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 36-year-old woman presents with 8 months of recurrent episodes of right upper quadrant pain lasting 1 to 2 hours after fatty meals, identical to biliary colic. She has no fever or jaundice, and liver enzymes and bilirubin are normal. Ultrasound shows no gallstones and a normal gallbladder wall and bile duct. A HIDA scan with cholecystokinin stimulation shows a gallbladder ejection fraction of 18% (normal >35%). What is the most appropriate management?', '["Reassurance and a low-fat diet indefinitely", "Endoscopic retrograde cholangiopancreatography with sphincterotomy", "Ursodeoxycholic acid dissolution therapy", "Sphincter of Oddi dysfunction as the diagnosis", "Laparoscopic cholecystectomy"]'::jsonb, 4, 'Biliary dyskinesia is a functional gallbladder disorder diagnosed by recurrent biliary-type pain with a low gallbladder ejection fraction, typically less than 35 percent, on HIDA scan with cholecystokinin stimulation, in the absence of gallstones. Laparoscopic cholecystectomy provides symptom relief in most patients with confirmed dyskinesia and is the definitive treatment. Reassurance alone does not help patients with documented dyskinesia and recurrent pain. ERCP is for common bile duct pathology, not gallbladder dyskinesia. Ursodeoxycholic acid dissolves cholesterol stones, which are absent here. Sphincter of Oddi dysfunction causes biliary pain but is associated with abnormal liver enzymes and a dilated bile duct, which are not present.', 'Hard', 110, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 24-year-old man presents with intermittent mild jaundice during periods of fasting or illness for the past 2 years. He feels well otherwise and has no abdominal pain, dark urine, or pale stools. Examination is normal apart from mild scleral icterus. Laboratory studies show total bilirubin 2.4 mg/dL with indirect bilirubin 2.1 mg/dL, normal alkaline phosphatase and transaminases, normal hemoglobin, normal reticulocyte count, and normal lactate dehydrogenase. What is the most likely diagnosis?', '["Hemolytic anemia", "Gilbert syndrome", "Crigler-Najjar syndrome type I", "Acute viral hepatitis", "Dubin-Johnson syndrome"]'::jsonb, 1, 'Unconjugated hyperbilirubinemia with a normal alkaline phosphatase, normal transaminases, and no hemolysis points to Gilbert syndrome, caused by reduced activity of UDP-glucuronosyltransferase, which impairs bilirubin conjugation. The diagnosis is supported by the history of mild intermittent jaundice during fasting or illness and the absence of hemolysis or liver disease. Hemolysis would cause anemia, reticulocytosis, and an elevated lactate dehydrogenase. Crigler-Najjar type I presents in infancy with severe unconjugated hyperbilirubinemia and kernicterus. Hepatitis causes elevated transaminases. Dubin-Johnson syndrome causes conjugated hyperbilirubinemia with a black liver, not unconjugated jaundice.', 'Medium', 111, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 30-year-old man is found to have a total bilirubin of 4.6 mg/dL with direct bilirubin 3.8 mg/dL during a routine health check. He has no symptoms, normal liver enzymes, and a normal abdominal ultrasound. A liver biopsy performed for evaluation shows a grossly black liver with pigment granules in hepatocytes but otherwise normal histology. What is the most likely diagnosis?', '["Rotor syndrome", "Dubin-Johnson syndrome", "Gilbert syndrome", "Crigler-Najjar syndrome type II", "Hemochromatosis"]'::jsonb, 1, 'Dubin-Johnson syndrome is an autosomal recessive disorder of conjugated bilirubin excretion caused by a defect in the MRP2 transporter, resulting in conjugated hyperbilirubinemia with a characteristically black liver on gross examination due to pigment deposition. Rotor syndrome also causes conjugated hyperbilirubinemia but the liver is normal in appearance and the defect is in bilirubin uptake. Gilbert syndrome causes unconjugated hyperbilirubinemia. Crigler-Najjar syndrome causes unconjugated hyperbilirubinemia from defective conjugation. Hemochromatosis causes iron overload with a bronze liver and diabetes, not isolated conjugated hyperbilirubinemia with a black liver.', 'Hard', 112, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 55-year-old woman presents with 3 weeks of progressive pruritus, jaundice, dark urine, and pale stools. She has no fever or abdominal pain. Examination shows jaundice and excoriations. Laboratory studies show total bilirubin 7.8 mg/dL with direct bilirubin 6.1 mg/dL, alkaline phosphatase 580 U/L, gamma-glutamyl transferase 420 U/L, and alanine aminotransferase 68 U/L. What is the most appropriate initial test to evaluate her jaundice?', '["CT of the abdomen with contrast", "Magnetic resonance cholangiopancreatography", "Abdominal ultrasound", "Endoscopic retrograde cholangiopancreatography", "Liver biopsy"]'::jsonb, 2, 'A cholestatic pattern with markedly elevated alkaline phosphatase and gamma-glutamyl transferase, conjugated hyperbilirubinemia, pruritus, and pale stools indicates impaired bile flow, and the first step is to distinguish extrahepatic obstruction from intrahepatic cholestasis with an abdominal ultrasound. Ultrasound can show a dilated common bile duct and identify stones or a mass. CT is more useful after ultrasound has characterized the level of obstruction. MRCP is the next step if ultrasound shows obstruction and further anatomic detail is needed. ERCP is therapeutic and is reserved for confirmed obstruction requiring intervention. Liver biopsy is used for intrahepatic cholestatic diseases after obstruction has been excluded.', 'Medium', 113, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 28-year-old woman presents with 1 year of chronic diarrhea, weight loss, fatigue, and bloating. She also has an itchy blistering rash on her elbows and knees. Laboratory studies show microcytic anemia with ferritin 8 ng/mL, low albumin, and normal thyroid studies. Stool studies are negative for infection. What is the best initial test to evaluate her malabsorption?', '["Tissue transglutaminase IgA antibody while the patient continues a gluten-containing diet", "Duodenal biopsy as the first test", "72-hour fecal fat collection", "Anti-gliadin IgG antibody", "Start a gluten-free diet immediately and test later"]'::jsonb, 0, 'Celiac disease is an autoimmune enteropathy triggered by gluten in genetically susceptible individuals, causing villous atrophy and malabsorption with diarrhea, weight loss, iron deficiency anemia, and dermatitis herpetiformis. The best initial test is tissue transglutaminase IgA antibody, which is highly sensitive and specific, provided the patient is consuming gluten and total IgA is normal. Duodenal biopsy confirms the diagnosis but is not the first step. Stool studies for fat are nonspecific. Anti-gliadin antibodies are less accurate than tissue transglutaminase. Genetic testing for HLA-DQ2/DQ8 has a high negative predictive value but is not the initial diagnostic test, and a gluten-free diet should not be started before testing because it can cause false-negative serology.', 'Medium', 114, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 52-year-old man with long-standing type 2 diabetes and a history of partial gastrectomy presents with 6 months of chronic watery diarrhea, bloating, and weight loss. He has no fever, blood in the stool, or abdominal pain. Examination shows decreased sensation in the feet and orthostatic hypotension. Laboratory studies show low vitamin B12, normal thyroid studies, and negative celiac serologies. Stool studies are negative for infection and there is no steatorrhea. What is the most appropriate diagnostic test?', '["Stool culture for bacterial pathogens", "Glucose hydrogen breath test", "Colonoscopy with random biopsies", "Fecal elastase", "Serum gastrin level"]'::jsonb, 1, 'Chronic diarrhea in a diabetic patient with autonomic neuropathy and a history of prior abdominal surgery suggests small intestinal bacterial overgrowth, in which excess bacteria deconjugate bile acids and ferment carbohydrates, causing bloating, diarrhea, and malabsorption. A glucose hydrogen breath test is the preferred noninvasive diagnostic test. Stool culture evaluates infectious diarrhea, which is typically acute. Colonoscopy with random biopsies is used for microscopic colitis, which presents with watery diarrhea but not the post-surgical bacterial overgrowth pattern. Fecal elastase tests for pancreatic exocrine insufficiency, which causes steatorrhea but is not suggested here. Serum gastrin is used for Zollinger-Ellison syndrome, which causes peptic ulcer disease and diarrhea from acid hypersecretion.', 'Hard', 115, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 40-year-old man presents with 3 days of profuse watery diarrhea, 10 to 12 stools per day, with mild cramping but no fever, blood, or mucus. He recently returned from a trip to Mexico. Despite being kept nil per os for 24 hours, he continues to have large-volume watery stools. Laboratory studies show sodium 132 mEq/L, potassium 3.1 mEq/L, and bicarbonate 18 mEq/L. Stool studies are negative for leukocytes. What type of diarrhea is most likely?', '["Osmotic diarrhea", "Inflammatory diarrhea", "Fatty diarrhea with malabsorption", "Secretory diarrhea", "Factitious diarrhea from laxative abuse"]'::jsonb, 3, 'Secretory diarrhea is characterized by large-volume watery stools that persist during fasting because of active intestinal secretion, most often from bacterial enterotoxins, bile acids, or neuroendocrine tumors. Osmotic diarrhea stops with fasting and is caused by unabsorbed solutes such as lactose or magnesium. Inflammatory diarrhea presents with blood, mucus, fever, and leukocytes in the stool. Fatty diarrhea is associated with steatorrhea and malabsorption. Factitious diarrhea from laxative abuse typically shows a low stool osmotic gap and a history of laxative use. The persistence of high-volume diarrhea during fasting is the key feature distinguishing secretory from osmotic diarrhea.', 'Medium', 116, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 45-year-old man presents with 2 weeks of constipation after starting tramadol for chronic back pain. He has bowel movements once or twice a week with hard stools and straining. He has no abdominal pain, rectal bleeding, weight loss, or fever. Examination is normal and there is no palpable mass or fecal impaction. He is otherwise healthy and takes no other medications. What is the most appropriate initial management?', '["Colonoscopy to evaluate for colon cancer", "Thyroid function testing", "Barium enema", "Stop tramadol immediately without alternative pain control", "Increase fiber and fluid intake and start a stimulant laxative such as senna"]'::jsonb, 4, 'Opioid-induced constipation is a common cause of new constipation in patients starting opioids, and the first step is to increase fiber and fluid intake and start a stimulant laxative such as senna, because opioids reduce intestinal motility and increase water absorption. Colonoscopy is indicated for red-flag features such as rectal bleeding, weight loss, or new constipation after age 50, but this patient is 45 with no alarm features. Thyroid testing is reasonable if no clear cause exists, but the temporal association with tramadol makes opioid-induced constipation most likely. A barium enema is not the initial test. Simply stopping the analgesic is not ideal when the patient needs pain control; adding a laxative is preferred.', 'Medium', 117, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 52-year-old woman presents with 2 years of progressive skin tightening of her fingers and face, Raynaud phenomenon, and heartburn that is worse at night. She also reports bloating, chronic diarrhea, and weight loss. Examination shows sclerodactyly and telangiectasias. Barium swallow shows a dilated esophagus with absent peristalsis and a patulous lower esophageal sphincter. What is the most likely cause of her gastrointestinal symptoms?', '["Systemic sclerosis with esophageal dysmotility and small intestinal bacterial overgrowth", "Achalasia", "Diabetic gastroparesis", "Crohn disease", "Zollinger-Ellison syndrome"]'::jsonb, 0, 'Systemic sclerosis causes fibrosis of the gastrointestinal tract, most commonly esophageal dysmotility with a patulous lower esophageal sphincter and absent peristalsis, leading to severe gastroesophageal reflux, and small bowel dysmotility with stasis that predisposes to bacterial overgrowth and malabsorption. The combination of skin tightening, Raynaud phenomenon, reflux, and bloating with diarrhea from bacterial overgrowth is classic. Achalasia causes dysphagia and regurgitation but not skin changes or bacterial overgrowth. Gastroparesis causes nausea and early satiety, typically in diabetes. Crohn disease causes transmural inflammation with fistulas, not scleroderma skin changes. Zollinger-Ellison syndrome causes peptic ulcer disease from gastrin hypersecretion.', 'Hard', 118, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 64-year-old man presents with 8 months of chronic diarrhea, weight loss, and intermittent gastrointestinal bleeding. He has a history of heart failure with preserved ejection fraction and carpal tunnel syndrome. Examination shows an enlarged tongue, periorbital purpura, and hepatomegaly. Laboratory studies show nephrotic-range proteinuria. A rectal biopsy shows Congo red staining with apple-green birefringence under polarized light. What is the most likely diagnosis?', '["Celiac disease", "Whipple disease", "Systemic amyloidosis", "Multiple myeloma alone without amyloid deposition", "Inflammatory bowel disease"]'::jsonb, 2, 'Systemic amyloidosis deposits misfolded proteins in tissues, and gastrointestinal involvement causes malabsorption, diarrhea, and gastrointestinal bleeding, while macroglossia and periorbital purpura are classic extraintestinal features. Congo red staining with apple-green birefringence under polarized light confirms amyloid deposition, and mass spectrometry identifies the amyloid type. Celiac disease causes malabsorption but not macroglossia or periorbital purpura. Whipple disease causes malabsorption with arthralgias and is diagnosed by periodic acid-Schiff-positive macrophages. Multiple myeloma is associated with AL amyloidosis but the question asks for the diagnosis of the gastrointestinal syndrome itself. Inflammatory bowel disease causes bloody diarrhea and does not produce macroglossia.', 'Hard', 119, 'MCQ'),
('0c62463e-ad4b-46ba-9b51-b82cafb60a66', 'A 22-year-old woman with anorexia nervosa is admitted after 3 months of severe caloric restriction with a body mass index of 15 kg/m2. She is hemodynamically stable with a heart rate of 48/min. Laboratory studies show phosphate 2.1 mg/dL, magnesium 1.5 mg/dL, and potassium 3.2 mEq/L. She is about to start nutritional rehabilitation. What is the most important step to prevent a life-threatening complication?', '["Start full-calorie enteral feeding immediately to reverse malnutrition", "Give intravenous fluids alone without electrolyte monitoring", "Give a multivitamin and start a regular diet", "Start a high-protein diet to rebuild muscle mass", "Check and replete serum phosphate, magnesium, and potassium, give thiamine, and start calories slowly with close monitoring"]'::jsonb, 4, 'Refeeding syndrome occurs when nutrition is reintroduced after prolonged starvation, causing insulin-mediated intracellular shifts of phosphate, magnesium, and potassium, which can lead to cardiac arrhythmias, respiratory failure, and death. The most important preventive step is to check and replete phosphate, magnesium, and potassium before feeding, start calories slowly at about 10 to 20 kcal/kg per day, and give thiamine. Starting full-calorie feeds immediately is dangerous and precipitates refeeding syndrome. Intravenous fluids alone do not prevent electrolyte shifts. Multivitamins alone are insufficient without specific electrolyte monitoring and repletion. A high-protein diet does not prevent refeeding syndrome and may worsen the metabolic demand.', 'Medium', 120, 'MCQ');
